    /**
     * The main OpenTelemetry API interface that provides access to all OpenTelemetry functionality.
     * This interface extends the IOTelTracerProvider and serves as the entry point for OpenTelemetry operations.
     *
     * @example
     * ```typescript
     * // Get a tracer from the API instance
     * const tracer = otelApi.getTracer("my-component");
     *
     * // Create a span
     * const span = tracer.startSpan("operation");
     *
     * // Access context manager
     * const currentContext = otelApi.context.active();
     *
     * // Access trace API
     * const activeSpan = otelApi.trace.getActiveSpan();
     * ```
     *
     * @since 3.4.0
     */
    interface IOTelApi extends IOTelTracerProvider {
        /**
         * The configuration object that contains all OpenTelemetry-specific settings.
         * This includes tracing configuration, error handlers, and other OpenTelemetry options.
         *
         * @remarks
         * Changes to this configuration after initialization may not take effect until
         * the next telemetry operation, depending on the implementation.
         */
        cfg: IOTelConfig;
        /**
         * The current {@link ITraceHost} instance for this IOTelApi instance, this is effectively
         * the OpenTelemetry ContextAPI instance without the static methods.
         * @returns The ContextManager instance
         */
        host: ITraceHost;
        /**
         * The current {@link ITraceApi} instance for this IOTelApi instance, this is
         * effectively the OpenTelemetry TraceAPI instance without the static methods.
         * @returns The current {@link ITraceApi} instance
         */
        trace: ITraceApi;
    }

    /**
     * Configuration interface for OpenTelemetry attribute limits.
     * These limits help control the size and number of attributes to prevent
     * excessive memory usage and ensure consistent performance.
     *
     * @example
     * ```typescript
     * const limits: IOTelAttributeLimits = {
     *   attributeCountLimit: 128,        // Maximum 128 attributes
     *   attributeValueLengthLimit: 4096  // Maximum 4KB per attribute value
     * };
     * ```
     *
     * @remarks
     * When limits are exceeded:
     * - Additional attributes beyond `attributeCountLimit` are dropped
     * - Attribute values longer than `attributeValueLengthLimit` are truncated
     * - The behavior may vary based on the specific implementation
     *
     * @since 3.4.0
     */
    interface IOTelAttributeLimits {
        /**
         * Maximum allowed length for attribute values in characters.
         *
         * @remarks
         * - Values longer than this limit will be truncated
         * - Applies to string attribute values only
         * - Numeric and boolean values are not affected by this limit
         * - Array values have this limit applied to each individual element
         *
         * @defaultValue 4096
         *
         * @example
         * ```typescript
         * // If attributeValueLengthLimit is 100:
         * span.setAttribute("description", "a".repeat(200)); // Will be truncated to 100 characters
         * span.setAttribute("count", 12345);                 // Not affected (number)
         * span.setAttribute("enabled", true);                // Not affected (boolean)
         * ```
         */
        attributeValueLengthLimit?: number;
        /**
         * Maximum number of attributes allowed per telemetry item.
         *
         * @remarks
         * - Attributes added beyond this limit will be dropped
         * - The order of attributes matters; earlier attributes take precedence
         * - This limit applies to the total count of attributes, regardless of their type
         * - Inherited or default attributes count toward this limit
         *
         * @defaultValue 128
         *
         * @example
         * ```typescript
         * // If attributeCountLimit is 5:
         * span.setAttributes({
         *   "attr1": "value1",  // Kept
         *   "attr2": "value2",  // Kept
         *   "attr3": "value3",  // Kept
         *   "attr4": "value4",  // Kept
         *   "attr5": "value5",  // Kept
         *   "attr6": "value6"   // Dropped (exceeds limit)
         * });
         * ```
         */
        attributeCountLimit?: number;
    }

    /**
     * Attributes is a map from string to attribute values.
     *
     * Note: only the own enumerable keys are counted as valid attribute keys.
     *
     * @since 3.4.0
     */
    interface IOTelAttributes {
        [key: string]: OTelAttributeValue | undefined;
    }

    /**
     * OpenTelemetry configuration interface
     * Provides configuration specific to the OpenTelemetry extensions
     */
    interface IOTelConfig {
        /**
         * Configuration interface for OpenTelemetry tracing functionality.
         * This interface contains all the settings that control how traces are created,
         * processed, and managed within the OpenTelemetry system.
         *
         * @example
         * ```typescript
         * const traceCfg: ITraceCfg = {
         *   serviceName: "my-service",
         *   generalLimits: {
         *     attributeCountLimit: 128,
         *     attributeValueLengthLimit: 4096
         *   },
         *   spanLimits: {
         *     attributeCountLimit: 128,
         *     linkCountLimit: 128,
         *     eventCountLimit: 128
         *   }
         * };
         * ```
         *
         * @since 3.4.0
         */
        traceCfg?: ITraceCfg;
        /**
         * Error handlers for OpenTelemetry operations.
         * This interface allows you to specify custom error handling logic for various
         * OpenTelemetry components, enabling better control over how errors are managed
         * within the OpenTelemetry system.
         *
         * @see {@link IOTelErrorHandlers}
         *
         * @example
         * ```typescript
         * const errorHandlers: IOTelErrorHandlers = {
         *   attribError: (message, key, value) => {
         *    console.warn(`Attribute error for ${key}:`, message);
         *  }
         * };
         * ```
         */
        errorHandlers?: IOTelErrorHandlers;
    }

    /**
     * Configuration interface for OpenTelemetry error handling callbacks.
     * Provides hooks to customize how different types of errors and diagnostic
     * messages are handled within the OpenTelemetry system.
     *
     * @example
     * ```typescript
     * const errorHandlers: IOTelErrorHandlers = {
     *   attribError: (message, key, value) => {
     *     console.warn(`Attribute error for ${key}:`, message);
     *   },
     *   spanError: (message, spanName) => {
     *     logger.error(`Span ${spanName} error:`, message);
     *   },
     *   warn: (message) => {
     *     logger.warn(message);
     *   },
     *   error: (message) => {
     *     logger.error(message);
     *   }
     * };
     * ```
     *
     * @remarks
     * If handlers are not provided, default behavior will be used:
     * - `attribError`: Throws an `OTelInvalidAttributeError`
     * - `spanError`: Logs to console or calls warn handler
     * - `debug`: Logs to console.log
     * - `warn`: Logs to console.warn
     * - `error`: Logs to console.error
     * - `notImplemented`: Logs to console.error
     *
     * @since 3.4.0
     */
    interface IOTelErrorHandlers {
        /**
         * Handles attribute-related errors, such as invalid attribute values or keys.
         * Called when an attribute operation fails validation or processing.
         *
         * @param message - Descriptive error message explaining what went wrong
         * @param key - The attribute key that caused the error
         * @param value - The attribute value that caused the error (may be of any type)
         *
         * @remarks
         * Common scenarios that trigger this handler:
         * - Invalid attribute key format
         * - Attribute value exceeds length limits
         * - Unsupported attribute value type
         * - Attribute count exceeds limits
         *
         * @default Throws an `OTelInvalidAttributeError`
         *
         * @example
         * ```typescript
         * attribError: (message, key, value) => {
         *   metrics.increment('otel.attribute.errors', { key, type: typeof value });
         *   logger.warn(`Attribute ${key} rejected: ${message}`);
         * }
         * ```
         */
        attribError?: (message: string, key: string, value: any) => void;
        /**
         * Handles span-related errors that occur during span operations.
         * Called when a span operation fails or encounters an unexpected condition.
         *
         * @param message - Descriptive error message explaining the span error
         * @param spanName - The name of the span that encountered the error
         *
         * @remarks
         * Common scenarios that trigger this handler:
         * - Span operation called on an ended span
         * - Invalid span configuration
         * - Span processor errors
         * - Context propagation failures
         *
         * @default Logs to console or calls the warn handler
         *
         * @example
         * ```typescript
         * spanError: (message, spanName) => {
         *   metrics.increment('otel.span.errors', { span_name: spanName });
         *   logger.error(`Span operation failed for "${spanName}": ${message}`);
         * }
         * ```
         */
        spanError?: (message: string, spanName: string) => void;
        /**
         * Handles debug-level diagnostic messages.
         * Used for detailed troubleshooting information that is typically
         * only relevant during development or when diagnosing issues.
         *
         * @param message - Debug message to be handled
         *
         * @remarks
         * Debug messages are typically:
         * - Verbose operational details
         * - Internal state information
         * - Performance metrics
         * - Development-time diagnostics
         *
         * @default Logs to console.log
         *
         * @example
         * ```typescript
         * debug: (message) => {
         *   if (process.env.NODE_ENV === 'development') {
         *     console.debug('[OTel Debug]', message);
         *   }
         * }
         * ```
         */
        debug?: (message: string) => void;
        /**
         * Handles warning-level messages for non-fatal issues.
         * Used for conditions that are unusual but don't prevent continued operation.
         *
         * @param message - Warning message to be handled
         *
         * @remarks
         * Warning scenarios include:
         * - Configuration issues that fall back to defaults
         * - Performance degradation
         * - Deprecated API usage
         * - Resource limit approaches
         *
         * @default Logs to console.warn
         *
         * @example
         * ```typescript
         * warn: (message) => {
         *   logger.warn('[OTel Warning]', message);
         *   metrics.increment('otel.warnings');
         * }
         * ```
         */
        warn?: (message: string) => void;
        /**
         * Handles general error conditions that may affect functionality.
         * Used for significant errors that should be investigated but may not be fatal.
         *
         * @param message - Error message to be handled
         *
         * @remarks
         * Error scenarios include:
         * - Failed network requests
         * - Configuration validation failures
         * - Resource allocation failures
         * - Unexpected runtime conditions
         *
         * @default Logs to console.error
         *
         * @example
         * ```typescript
         * error: (message) => {
         *   logger.error('[OTel Error]', message);
         *   errorReporting.captureException(new Error(message));
         * }
         * ```
         */
        error?: (message: string) => void;
        /**
         * Handles errors related to unimplemented functionality.
         * Called when a method or feature is not yet implemented or is intentionally
         * disabled in the current configuration.
         *
         * @param message - Message describing the unimplemented functionality
         *
         * @remarks
         * Common scenarios:
         * - Placeholder methods that haven't been implemented
         * - Features disabled in the current build
         * - Platform-specific functionality not available
         * - Optional features not included in the configuration
         *
         * @default Logs to console.error
         *
         * @example
         * ```typescript
         * notImplemented: (message) => {
         *   logger.warn(`[OTel Not Implemented] ${message}`);
         *   if (process.env.NODE_ENV === 'development') {
         *     console.trace('Not implemented method called');
         *   }
         * }
         * ```
         */
        notImplemented?: (message: string) => void;
    }

    interface IOTelExceptionWithCode {
        code: string | number;
        name?: string;
        message?: string;
        stack?: string;
    }

    interface IOTelExceptionWithMessage {
        code?: string | number;
        message: string;
        name?: string;
        stack?: string;
    }

    interface IOTelExceptionWithName {
        code?: string | number;
        message?: string;
        name: string;
        stack?: string;
    }

    /**
     * Enhanced high-resolution time interface that extends the base tuple with additional properties.
     * Provides a more structured way to work with high-resolution timestamps.
     *
     * @example
     * ```typescript
     * const hrTime: IOTelHrTime = {
     *   0: 1609459200,     // seconds since Unix epoch
     *   1: 500000000,      // nanoseconds (0-999,999,999)
     * };
     * ```
     *
     * @since 3.4.0
     */
    interface IOTelHrTime extends OTelHrTimeBase {
        /**
         * Seconds since Unix epoch (January 1, 1970 00:00:00 UTC).
         * Must be a non-negative integer.
         */
        0: number;
        /**
         * Nanoseconds within the second specified by index 0.
         * Must be in the range [0, 999999999].
         */
        1: number;
    }

    /**
     * Provides an OpenTelemetry compatible interface for spans conforming to the OpenTelemetry API specification (v1.9.0).
     *
     * A span represents an operation within a trace and is the fundamental unit of work in distributed tracing.
     * Spans can be thought of as a grouping mechanism for a set of operations that are executed as part of
     * a single logical unit of work, providing timing information and contextual data about the operation.
     *
     * Spans form a tree structure within a trace, with a single root span that may have zero or more child spans,
     * which in turn may have their own children. This hierarchical structure allows for detailed analysis of
     * complex, multi-step operations across distributed systems.
     *
     * @since 3.4.0
     *
     * @remarks
     * - All spans created by this library implement the ISpan interface and extend the IReadableSpan interface
     * - Spans should be ended by calling `end()` when the operation completes
     * - Once ended, spans should generally not be used for further operations
     * - Spans automatically track timing information from creation to end
     *
     * @example
     * ```typescript
     * // Basic span usage
     * const span = tracer.startSpan('user-authentication');
     * span.setAttribute('user.id', '12345');
     * span.setAttribute('auth.method', 'oauth2');
     *
     * try {
     *   const result = await authenticateUser();
     *   span.setStatus({ code: SpanStatusCode.OK });
     *   span.setAttribute('auth.success', true);
     * } catch (error) {
     *   span.recordException(error);
     *   span.setStatus({
     *     code: SpanStatusCode.ERROR,
     *     message: 'Authentication failed'
     *   });
     * } finally {
     *   span.end();
     * }
     * ```
     */
    interface IOTelSpan {
        /**
         * Returns the span context object associated with this span.
         *
         * The span context is an immutable, serializable identifier that uniquely identifies
         * this span within a trace. It contains the trace ID, span ID, and trace flags that
         * can be used to create new child spans or propagate trace context across process boundaries.
         *
         * The returned span context remains valid even after the span has ended, making it
         * useful for asynchronous operations and cross-service communication.
         *
         * @returns The immutable span context associated with this span
         *
         * @remarks
         * - The span context is the primary mechanism for trace propagation
         * - Context can be serialized and transmitted across network boundaries
         * - Contains trace ID (unique to the entire trace) and span ID (unique to this span)
         *
         * @example
         * ```typescript
         * const span = tracer.startSpan('parent-operation');
         * const spanContext = span.spanContext();
         *
         * // Use context to create child spans in other parts of the system
         * const childSpan = tracer.startSpan('child-operation', {
         *   parent: spanContext
         * });
         *
         * // Context can be serialized for cross-service propagation
         * const traceId = spanContext.traceId;
         * const spanId = spanContext.spanId;
         * ```
         */
        spanContext(): IDistributedTraceContext;
        /**
         * Sets a single attribute on the span with the specified key and value.
         *
         * Attributes provide contextual information about the operation represented by the span.
         * They are key-value pairs that help with filtering, grouping, and understanding spans
         * in trace analysis tools. Attributes should represent meaningful properties of the operation.
         *
         * @param key - The attribute key, should be descriptive and follow naming conventions
         * @param value - The attribute value; null or undefined values are invalid and result in undefined behavior
         *
         * @returns This span instance for method chaining
         *
         * @remarks
         * - Attribute keys should follow semantic conventions when available
         * - Common attributes include service.name, http.method, db.statement, etc.
         * - Setting null or undefined values is invalid and may cause unexpected behavior
         * - Attributes set after span creation don't affect sampling decisions
         *
         * @example
         * ```typescript
         * const span = tracer.startSpan('http-request');
         *
         * // Set individual attributes with descriptive keys
         * span.setAttribute('http.method', 'POST')
         *     .setAttribute('http.url', 'https://api.example.com/users')
         *     .setAttribute('http.status_code', 201)
         *     .setAttribute('user.id', '12345')
         *     .setAttribute('request.size', 1024);
         * ```
         */
        setAttribute(key: string, value: OTelAttributeValue): this;
        /**
         * Sets multiple attributes on the span at once using an attributes object.
         *
         * This method allows efficient batch setting of multiple attributes in a single call.
         * All attributes in the provided object will be added to the span, supplementing any
         * existing attributes (duplicate keys will be overwritten).
         *
         * @param attributes - An object containing key-value pairs to set as span attributes
         *
         * @returns This span instance for method chaining
         *
         * @remarks
         * - Null or undefined attribute values are invalid and will result in undefined behavior
         * - More efficient than multiple `setAttribute` calls for bulk operations
         * - Existing attributes with the same keys will be overwritten
         *
         * @example
         * ```typescript
         * const span = tracer.startSpan('database-query');
         *
         * // Set multiple attributes efficiently
         * span.setAttributes({
         *   'db.system': 'postgresql',
         *   'db.name': 'user_database',
         *   'db.table': 'users',
         *   'db.operation': 'SELECT',
         *   'db.rows_affected': 5,
         *   'query.duration_ms': 15.7
         * });
         * ```
         */
        setAttributes(attributes: IOTelAttributes): this;
        /**
         * The {@link IAttributeContainer | attribute container} associated with this span, providing
         * advanced attribute management capabilities. Rather than using the {@link IReadableSpan#attributes}
         * directly which returns a readonly {@link IOTelAttributes} map that is a snapshot of the attributes at
         * the time of access, the attribute container offers methods to get, set, delete, and iterate over attributes
         * with fine-grained control.
         * It is recommended that you only access the {@link IReadableSpan#attributes} property sparingly due to the
         * performance cost of taking a snapshot of all attributes.
         */
        readonly attribContainer: IAttributeContainer;
        /**
         * Sets the status of the span to indicate the success or failure of the operation.
         *
         * The span status provides a standardized way to indicate whether the operation
         * completed successfully, encountered an error, or is in an unknown state.
         * This status is used by observability tools to provide meaningful insights
         * about system health and operation outcomes.
         *
         * @param status - The status object containing code and optional message
         *
         * @returns This span instance for method chaining
         *
         * @remarks
         * - Default status is UNSET until explicitly set
         * - Setting status overrides any previous status values
         * - ERROR status should be accompanied by a descriptive message when possible
         * - Status should reflect the final outcome of the operation
         *
         * @example
         * ```typescript
         * const span = tracer.startSpan('payment-processing');
         *
         * try {
         *   const result = await processPayment(paymentData);
         *
         *   // Indicate successful completion
         *   span.setStatus({
         *     code: SpanStatusCode.OK
         *   });
         *
         * } catch (error) {
         *   // Indicate operation failed
         *   span.setStatus({
         *     code: SpanStatusCode.ERROR,
         *     message: 'Payment processing failed: ' + error.message
         *   });
         *
         *   span.recordException(error);
         * }
         * ```
         */
        setStatus(status: IOTelSpanStatus): this;
        /**
         * Updates the name of the span, overriding the name provided during creation.
         *
         * Span names should be descriptive and represent the operation being performed.
         * Updating the name can be useful when the operation's scope becomes clearer
         * during execution, or when implementing generic spans that need specific naming
         * based on runtime conditions.
         *
         * @param name - The new name for the span, should be descriptive of the operation
         *
         * @returns This span instance for method chaining
         *
         * @remarks
         * - Name updates may affect sampling behavior depending on implementation
         * - Choose names that are meaningful but not too specific to avoid cardinality issues
         * - Follow naming conventions consistent with your observability strategy
         * - Consider the impact on existing traces and dashboards when changing names
         *
         * @example
         * ```typescript
         * const span = tracer.startSpan('generic-operation');
         *
         * // Update name based on runtime determination
         * if (operationType === 'user-registration') {
         *   span.updateName('user-registration');
         *   span.setAttribute('operation.type', 'registration');
         * } else if (operationType === 'user-login') {
         *   span.updateName('user-authentication');
         *   span.setAttribute('operation.type', 'authentication');
         * }
         * ```
         */
        updateName(name: string): this;
        /**
         * Marks the end of the span's execution and records the end timestamp.
         *
         * This method finalizes the span and makes it available for export to tracing systems.
         * Once ended, the span should not be used for further operations. The span's duration
         * is calculated from its start time to the end time provided or current time.
         *
         * @param endTime - Optional end time; if not provided, current time is used
         *
         * @remarks
         * - This method does NOT return `this` to discourage chaining after span completion
         * - Ending a span has no effect on child spans, which may continue running
         * - Child spans can be ended independently after their parent has ended
         * - The span becomes eligible for export once ended
         * - Calling end() multiple times has no additional effect
         *
         * @example
         * ```typescript
         * const span = tracer.startSpan('file-processing');
         *
         * try {
         *   // Perform the operation
         *   const result = await processFile(filePath);
         *
         *   // Record success
         *   span.setStatus({ code: SpanStatusCode.OK });
         *   span.setAttribute('file.size', result.size);
         *
         * } catch (error) {
         *   span.recordException(error);
         *   span.setStatus({
         *     code: SpanStatusCode.ERROR,
         *     message: error.message
         *   });
         * } finally {
         *   // Always end the span
         *   span.end();
         *   // Don't use span after this point
         * }
         *
         * // Custom end time example
         * const customEndTime = Date.now() * 1000000; // nanoseconds
         * span.end(customEndTime);
         * ```
         */
        end(endTime?: OTelTimeInput): void;
        /**
         * Returns whether this span is actively recording information.
         *
         * A recording span accepts and stores attributes, events, status, and other span data.
         * Non-recording spans (typically due to sampling decisions) may ignore operations
         * like setAttribute() to optimize performance. This method allows conditional
         * logic to avoid expensive operations on non-recording spans.
         *
         * @returns True if the span is actively recording information, false otherwise
         *
         * @remarks
         * - Recording status is typically determined at span creation time
         * - Non-recording spans still provide valid span context for propagation
         * - Use this check to avoid expensive attribute calculations for non-recording spans
         * - Recording status remains constant throughout the span's lifetime
         *
         * @example
         * ```typescript
         * const span = tracer.startSpan('data-processing');
         *
         * // Only perform expensive operations if span is recording
         * if (span.isRecording()) {
         *   const metadata = await expensiveMetadataCalculation();
         *   span.setAttributes({
         *     'process.metadata': JSON.stringify(metadata),
         *     'process.complexity': metadata.complexity,
         *     'process.estimated_duration': metadata.estimatedMs
         *   });
         * }
         *
         * // Always safe to set basic attributes
         * span.setAttribute('process.started', true);
         * ```
         */
        isRecording(): boolean;
        /**
         * Records an exception as a span event with automatic error status handling.
         *
         * This method captures exception information and automatically creates a span event
         * with standardized exception attributes. It's the recommended way to handle errors
         * within spans, providing consistent error reporting across the application.
         *
         * @param exception - The exception to record; accepts string messages or Error objects
         * @param time - Optional timestamp for when the exception occurred; defaults to current time
         *
         * @remarks
         * - Automatically extracts exception type, message, and stack trace when available
         * - Creates a standardized span event with exception details
         * - Does NOT automatically set span status to ERROR - call setStatus() explicitly if needed
         * - Exception events are useful for debugging and error analysis
         *
         * @example
         * ```typescript
         * const span = tracer.startSpan('risky-operation');
         *
         * try {
         *   await performRiskyOperation();
         *   span.setStatus({ code: SpanStatusCode.OK });
         *
         * } catch (error) {
         *   // Record the exception details
         *   span.recordException(error);
         *
         *   // Explicitly set error status
         *   span.setStatus({
         *     code: SpanStatusCode.ERROR,
         *     message: 'Operation failed due to: ' + error.message
         *   });
         *
         *   // Re-throw if needed
         *   throw error;
         * } finally {
         *   span.end();
         * }
         *
         * // Recording string exceptions
         * span.recordException('Custom error message occurred');
         *
         * // Recording with custom timestamp
         * const errorTime = Date.now() * 1000000; // nanoseconds
         * span.recordException(error, errorTime);
         * ```
         */
        recordException(exception: OTelException, time?: OTelTimeInput): void;
    }

    /**
     * A SpanContext represents the portion of a {@link IOTelSpan} which must be
     * serialized and propagated along side of a {@link IOTelBaggage}.
     */
    interface IOTelSpanContext extends IDistributedTraceInit {
        /**
         * Trace flags to propagate.
         *
         * It is represented as 1 byte (bitmap). Bit to represent whether trace is
         * sampled or not. When set, the least significant bit documents that the
         * caller may have recorded trace data. A caller who does not record trace
         * data out-of-band leaves this flag unset.
         *
         * see {@link eW3CTraceFlags} for valid flag values.
         */
        traceFlags: number;
    }

    /**
     * Provides an OpenTelemetry like Interface for the Open Telemetry Api (1.9.0) SpanOptions
     * type. Where SpanOptions are options that can be used to configure a span.
     */
    interface IOTelSpanOptions {
        /**
         * The SpanKind of a span of this span, this is used to specify
         * the relationship between the span and its parent span.
         * @see {@link eOTelSpanKind} for possible values.
         * @default eOTelSpanKind.INTERNAL
         */
        kind?: OTelSpanKind;
        /**
         * A span's attributes
         */
        attributes?: IOTelAttributes;
        /** A manually specified start time for the created `Span` object. */
        startTime?: OTelTimeInput;
        /** The new span should be a root span. (Ignore parent from context). */
        root?: boolean;
        /** Specify whether the span should be a recording span, default is true */
        recording?: boolean;
    }

    interface IOTelSpanStatus {
        /**
         * The status code of this message.
         */
        code: eOTelSpanStatusCode;
        /**
         * A developer-facing error message.
         */
        message?: string;
    }

    /**
     * OpenTelemetry tracer interface for creating and managing spans within a trace.
     *
     * A tracer is responsible for creating spans that represent units of work within a distributed system.
     * Each tracer is typically associated with a specific instrumentation library or component,
     * allowing for fine-grained control over how different parts of an application generate telemetry.
     *
     * @example
     * ```typescript
     * // Get a tracer instance
     * const tracer = otelApi.getTracer('my-service');
     *
     * // Create a simple span
     * const span = tracer.startSpan('database-query');
     * span.setAttribute('db.operation', 'SELECT');
     * span.end();
     *
     * // Create an active span with automatic context management
     * tracer.startActiveSpan('process-request', (span) => {
     *   span.setAttribute('request.id', '12345');
     *
     *   // Any spans created within this block will be children of this span
     *   processRequest();
     *
     *   span.end();
     * });
     * ```
     *
     * @see {@link IReadableSpan} - Interface for individual spans
     * @see {@link IOTelSpanOptions} - Configuration options for span creation
     *
     * @since 3.4.0
     */
    interface IOTelTracer {
        /**
         * Creates and starts a new span without setting it as the active span in the current context.
         *
         * This method creates a span but does NOT modify the current execution context.
         * The caller is responsible for managing the span's lifecycle, including calling `end()`
         * when the operation completes.
         *
         * @param name - The name of the span, should be descriptive of the operation being traced
         * @param options - Optional configuration for span creation (parent context, attributes, etc.)
         *
         * @returns The newly created span, or null if span creation failed
         *
         * @remarks
         * - The returned span must be manually ended by calling `span.end()`
         * - This span will not automatically become the parent for spans created in nested operations
         * - Use `startActiveSpan` if you want automatic context management
         *
         * @example
         * ```typescript
         * const span = tracer.startSpan('database-operation');
         * if (span) {
         *   try {
         *     span.setAttribute('db.table', 'users');
         *     span.setAttribute('db.operation', 'SELECT');
         *
         *     // Perform database operation
         *     const result = await db.query('SELECT * FROM users');
         *
         *     span.setAttributes({
         *       'db.rows_affected': result.length,
         *       'operation.success': true
         *     });
         *   } catch (error) {
         *     span.setStatus({
         *       code: SpanStatusCode.ERROR,
         *       message: error.message
         *     });
         *     span.recordException(error);
         *   } finally {
         *     span.end(); // Always end the span
         *   }
         * }
         * ```
         */
        startSpan(name: string, options?: IOTelSpanOptions): IReadableSpan | null;
        /**
         * Creates and starts a new span, sets it as the active span in the current context,
         * and executes a provided function within this context.
         *
         * This method creates a span, makes it active during the execution of the provided
         * function, and automatically ends the span when the function completes (or throws).
         * This provides automatic span lifecycle management and context propagation.
         *
         * @param name - The name of the span, should be descriptive of the operation being traced
         * @param options - Optional configuration for span creation (parent context, attributes, etc.)
         * @param fn - The function to execute within the span's active context
         *
         * @returns The result of executing the provided function
         *
         * @remarks
         * - The span is automatically ended when the function completes or throws an exception
         * - The span becomes the active parent for any spans created within the function
         * - If the function throws an error, the span status is automatically set to ERROR
         * - This is the recommended method for most tracing scenarios due to automatic lifecycle management
         * - Multiple overloads available for different parameter combinations
         *
         * @example
         * ```typescript
         * // Synchronous operation with just name and function
         * const result = tracer.startActiveSpan('user-service', (span) => {
         *   span.setAttribute('operation', 'get-user-details');
         *   return { user: getUserData(), timestamp: new Date().toISOString() };
         * });
         *
         * // With options
         * const result2 = tracer.startActiveSpan('database-query',
         *   { attributes: { 'db.table': 'users' } },
         *   (span) => {
         *     span.setAttribute('db.operation', 'SELECT');
         *     return database.getUser('123');
         *   }
         * );
         *
         * // With full context control
         * const result3 = tracer.startActiveSpan('external-api',
         *   { attributes: { 'service.name': 'payment-api' } },
         *   currentContext,
         *   async (span) => {
         *     try {
         *       const response = await fetch('/api/payment');
         *       span.setAttributes({
         *         'http.status_code': response.status,
         *         'operation.success': response.ok
         *       });
         *       return response.json();
         *     } catch (error) {
         *       span.setAttribute('error.type', error.constructor.name);
         *       throw error; // Error automatically recorded
         *     }
         *   }
         * );
         * ```
         */
        startActiveSpan<F extends (span: IReadableSpan) => unknown>(name: string, fn: F): ReturnType<F>;
        startActiveSpan<F extends (span: IReadableSpan) => unknown>(name: string, options: IOTelSpanOptions, fn: F): ReturnType<F>;
    }

    interface IOTelTracerOptions {
        /**
         * The schemaUrl of the tracer or instrumentation library
         */
        schemaUrl?: string;
    }

    /**
     * OpenTelemetry Trace API for getting tracers.
     * This provides the standard OpenTelemetry trace API entry point.
     */
    interface IOTelTracerProvider {
        /**
         * Returns a Tracer, creating one if one with the given name and version is
         * not already created. This may return
         * - The same Tracer instance if one has already been created with the same name and version
         * - A new Tracer instance if one has not already been created with the same name and version
         * - A non-operational Tracer if the provider is not operational
         *
         * @param name - The name of the tracer or instrumentation library.
         * @param version - The version of the tracer or instrumentation library.
         * @param options - The options of the tracer or instrumentation library.
         * @returns Tracer A Tracer with the given name and version
         */
        getTracer(name: string, version?: string, options?: IOTelTracerOptions): IOTelTracer;
        /**
         * Forces the tracer provider to flush any buffered data.
         * @returns A promise that resolves when the flush is complete.
         */
        forceFlush?: () => IPromise<void> | void;
        /**
         * Shuts down the tracer provider and releases any resources.
         * @returns A promise that resolves when the shutdown is complete.
         */
        shutdown?: () => IPromise<void> | void;
    }

    /**
     * Provides an OpenTelemetry compatible Interface for the Open Telemetry Api (1.9.0) TraceState type.
     *
     * The TraceState is a list of key/value pairs that are used to propagate
     * vendor-specific trace information across different distributed tracing systems.
     * The TraceState is used to store the state of a trace across different
     * distributed tracing systems, and it is used to ensure that the trace information
     * is consistent across different systems.
     *
     * Instances of TraceState are immutable, and the methods on this interface
     * return a new instance of TraceState with the updated values.
     */
    interface IOTelTraceState {
        /**
         * Create a new TraceState which inherits from this TraceState and has the
         * given key set.
         * The new entry will always be added in the front of the list of states.
         *
         * @param key - key of the TraceState entry.
         * @param value - value of the TraceState entry.
         */
        set(key: string, value: string): IOTelTraceState;
        /**
         * Return a new TraceState which inherits from this TraceState but does not
         * contain the given key.
         *
         * @param key - the key for the TraceState entry to be removed.
         */
        unset(key: string): IOTelTraceState;
        /**
         * Returns the value to which the specified key is mapped, or `undefined` if
         * this map contains no mapping for the key.
         *
         * @param key - with which the specified value is to be associated.
         * @returns the value to which the specified key is mapped, or `undefined` if
         *     this map contains no mapping for the key.
         */
        get(key: string): string | undefined;
        /**
         * Serializes the TraceState to a `list` as defined below. The `list` is a series of `list-members`
         * separated by commas `,`, and a list-member is a key/value pair separated by an equals sign `=`.
         * Spaces and horizontal tabs surrounding `list-members` are ignored. There can be a maximum of 32
         * `list-members` in a `list`.
         *
         * If the resulting serialization is limited to no longer than 512 bytes, if the combination of
         * keys and values exceeds this limit, the serialization will be truncated to the last key/value pair
         * that fits within the limit. The serialization will be returned as a string.
         *
         * This is different from the {@link IW3cTraceState} serialization which returns an array of strings where each
         * string is limited to 512 bytes and the array is limited to 32 strings. Thus the OpenTelemetry serialization
         * will only return the first single string that fits within the limie.
         *
         * @returns the serialized string.
         */
        serialize(): string;
    }

    /** IPayloadData describes interface of payload sent via POST channel */
    interface IPayloadData {
        urlString: string;
        data: Uint8Array | string;
        headers?: {
            [name: string]: string;
        };
        timeout?: number;
        disableXhrSync?: boolean;
        disableFetchKeepAlive?: boolean;
        sendReason?: SendRequestReason;
    }

    /**
     * This interface identifies the details of an internal performance event - it does not represent an outgoing reported event
     */
    interface IPerfEvent {
        /**
         * The name of the performance event
         */
        name: string;
        /**
         * The start time of the performance event
         */
        start: number;
        /**
         * The payload (contents) of the perfEvent, may be null or only set after the event has completed depending on
         * the runtime environment.
         */
        payload: any;
        /**
         * Is this occurring from an asynchronous event
         */
        isAsync: boolean;
        /**
         * Identifies the total inclusive time spent for this event, including the time spent for child events,
         * this will be undefined until the event is completed
         */
        time?: number;
        /**
         * Identifies the exclusive time spent in for this event (not including child events),
         * this will be undefined until the event is completed.
         */
        exTime?: number;
        /**
         * The Parent event that was started before this event was created
         */
        parent?: IPerfEvent;
        /**
         * The child perf events that are contained within the total time of this event.
         */
        childEvts?: IPerfEvent[];
        /**
         * Identifies whether this event is a child event of a parent
         */
        isChildEvt: () => boolean;
        /**
         * Get the names additional context associated with this perf event
         */
        getCtx?: (key: string) => any;
        /**
         * Set the named additional context to be associated with this perf event, this will replace any existing value
         */
        setCtx?: (key: string, value: any) => void;
        /**
         * Mark this event as completed, calculating the total execution time.
         */
        complete: () => void;
    }

    /**
     * This defines an internal performance manager for tracking and reporting the internal performance of the SDK -- It does
     * not represent or report any event to the server.
     */
    interface IPerfManager {
        /**
         * Create a new event and start timing, the manager may return null/undefined to indicate that it does not
         * want to monitor this source event.
         * @param src - The source name of the event
         * @param payloadDetails - An optional callback function to fetch the payload details for the event.
         * @param isAsync - Is the event occurring from a async event
         */
        create(src: string, payloadDetails?: () => any, isAsync?: boolean): IPerfEvent | null | undefined;
        /**
         * Complete the perfEvent and fire any notifications.
         * @param perfEvent - Fire the event which will also complete the passed event
         */
        fire(perfEvent: IPerfEvent): void;
        /**
         * Set an execution context value
         * @param key - The context key name
         * @param value - The value
         */
        setCtx(key: string, value: any): void;
        /**
         * Get the execution context value
         * @param key - The context key
         */
        getCtx(key: string): any;
    }

    /**
     * Identifies an interface to a host that can provide an IPerfManager implementation
     */
    interface IPerfManagerProvider {
        /**
         * Get the current performance manager
         */
        getPerfMgr(): IPerfManager;
        /**
         * Set the current performance manager
         * @param perfMgr - The performance manager
         */
        setPerfMgr(perfMgr: IPerfManager): void;
    }

    interface IPlugin {
        /**
         * Initialize plugin loaded by SDK
         * @param config - The config for the plugin to use
         * @param core - The current App Insights core to use for initializing this plugin instance
         * @param extensions - The complete set of extensions to be used for initializing the plugin
         * @param pluginChain - [Optional] specifies the current plugin chain which identifies the
         * set of plugins and the order they should be executed for the current request.
         */
        initialize: (config: IConfiguration, core: IAppInsightsCore, extensions: IPlugin[], pluginChain?: ITelemetryPluginChain) => void;
        /**
         * Returns a value that indicates whether the plugin has already been previously initialized.
         * New plugins should implement this method to avoid being initialized more than once.
         */
        isInitialized?: () => boolean;
        /**
         * Tear down the plugin and remove any hooked value, the plugin should be removed so that it is no longer initialized and
         * therefore could be re-initialized after being torn down. The plugin should ensure that once this has been called any further
         * processTelemetry calls are ignored and it just calls the processNext() with the provided context.
         * @param unloadCtx - This is the context that should be used during unloading.
         * @param unloadState - The details / state of the unload process, it holds details like whether it should be unloaded synchronously or asynchronously and the reason for the unload.
         * @returns boolean - true if the plugin has or will call processNext(), this for backward compatibility as previously teardown was synchronous and returned nothing.
         */
        teardown?: (unloadCtx: IProcessTelemetryUnloadContext, unloadState?: ITelemetryUnloadState) => void | boolean;
        /**
         * Extension name
         */
        readonly identifier: string;
        /**
         * Plugin version (available in data.properties.version in common schema)
         */
        readonly version?: string;
        /**
         * The App Insights core to use for backward compatibility.
         * Therefore the interface will be able to access the core without needing to cast to "any".
         * [optional] any 3rd party plugins which are already implementing this interface don't fail to compile.
         */
        core?: IAppInsightsCore;
    }

    /**
     * The current context for the current call to processTelemetry(), used to support sharing the same plugin instance
     * between multiple AppInsights instances
     */
    interface IProcessTelemetryContext extends IBaseProcessingContext {
        /**
         * Call back for telemetry processing before it it is sent
         * @param env - This is the current event being reported
         * @returns boolean (true) if there is no more plugins to process otherwise false or undefined (void)
         */
        processNext: (env: ITelemetryItem) => boolean | void;
        /**
         * Create a new context using the core and config from the current instance, returns a new instance of the same type
         * @param plugins - The execution order to process the plugins, if null or not supplied
         *                  then the current execution order will be copied.
         * @param startAt - The plugin to start processing from, if missing from the execution
         *                  order then the next plugin will be NOT set.
         */
        createNew: (plugins?: IPlugin[] | ITelemetryPluginChain, startAt?: IPlugin) => IProcessTelemetryContext;
    }

    /**
     * The current context for the current call to teardown() implementations, used to support when plugins are being removed
     * or the SDK is being unloaded.
     */
    interface IProcessTelemetryUnloadContext extends IBaseProcessingContext {
        /**
         * This Plugin has finished unloading, so unload the next one
         * @param uploadState - The state of the unload process
         * @returns boolean (true) if there is no more plugins to process otherwise false or undefined (void)
         */
        processNext: (unloadState: ITelemetryUnloadState) => boolean | void;
        /**
         * Create a new context using the core and config from the current instance, returns a new instance of the same type
         * @param plugins - The execution order to process the plugins, if null or not supplied
         *                  then the current execution order will be copied.
         * @param startAt - The plugin to start processing from, if missing from the execution
         *                  order then the next plugin will be NOT set.
         */
        createNew: (plugins?: IPlugin[] | ITelemetryPluginChain, startAt?: IPlugin) => IProcessTelemetryUnloadContext;
    }

    /**
     * The current context for the current call to the plugin update() implementations, used to support the notifications
     * for when plugins are added, removed or the configuration was changed.
     */
    interface IProcessTelemetryUpdateContext extends IBaseProcessingContext {
        /**
         * This Plugin has finished unloading, so unload the next one
         * @param updateState - The update State
         * @returns boolean (true) if there is no more plugins to process otherwise false or undefined (void)
         */
        processNext: (updateState: ITelemetryUpdateState) => boolean | void;
        /**
         * Create a new context using the core and config from the current instance, returns a new instance of the same type
         * @param plugins - The execution order to process the plugins, if null or not supplied
         *                  then the current execution order will be copied.
         * @param startAt - The plugin to start processing from, if missing from the execution
         *                  order then the next plugin will be NOT set.
         */
        createNew: (plugins?: IPlugin[] | ITelemetryPluginChain, startAt?: IPlugin) => IProcessTelemetryUpdateContext;
    }

    /**
     * Create a Promise object that represents the eventual completion (or failure) of an asynchronous operation and its resulting value.
     * This interface definition, closely mirrors the typescript / javascript PromiseLike<T> and Promise<T> definitions as well as providing
     * simular functions as that provided by jQuery deferred objects.
     *
     * The returned Promise is a proxy for a value not necessarily known when the promise is created. It allows you to associate handlers
     * with an asynchronous action's eventual success value or failure reason. This lets asynchronous methods return values like synchronous
     * methods: instead of immediately returning the final value, the asynchronous method returns a promise to supply the value at some point
     * in the future.
     *
     * A Promise is in one of these states:
     * <ul>
     * <li> pending: initial state, neither fulfilled nor rejected.
     * <li> fulfilled: meaning that the operation was completed successfully.
     * <li> rejected: meaning that the operation failed.
     * </ul>
     *
     * A pending promise can either be fulfilled with a value or rejected with a reason (error). When either of these options happens, the
     * associated handlers queued up by a promise's then method are called synchronously. If the promise has already been fulfilled or rejected
     * when a corresponding handler is attached, the handler will be called synchronously, so there is no race condition between an asynchronous
     * operation completing and its handlers being attached.
     *
     * As the `then()` and `catch()` methods return promises, they can be chained.
     * @typeParam T - Identifies the expected return type from the promise
     */
    interface IPromise<T> extends PromiseLike<T>, Promise<T> {
        /**
         * Returns a string representation of the current state of the promise. The promise can be in one of four states.
         * <ul>
         * <li> <b>"pending"</b>: The promise is not yet in a completed state (neither "rejected"; or "resolved").</li>
         * <li> <b>"resolved"</b>: The promise is in the resolved state.</li>
         * <li> <b>"rejected"</b>: The promise is in the rejected state.</li>
         * </ul>
         * @example
         * ```ts
         * let doResolve;
         * let promise: IPromise<any> = createSyncPromise((resolve) => {
         *  doResolve = resolve;
         * });
         *
         * let state: string = promise.state();
         * console.log("State: " + state);      // State: pending
         * doResolve(true);                     // Promise will resolve synchronously as it's a synchronous promise
         * console.log("State: " + state);      // State: resolved
         * ```
         */
        state?: string;
        /**
         * Attaches callbacks for the resolution and/or rejection of the Promise.
         * @param onResolved - The callback to execute when the Promise is resolved.
         * @param onRejected - The callback to execute when the Promise is rejected.
         * @returns A Promise for the completion of which ever callback is executed.
         * @example
         * ```ts
         * const promise1 = createPromise((resolve, reject) => {
         *   resolve('Success!');
         * });
         *
         * promise1.then((value) => {
         *   console.log(value);
         *   // expected output: "Success!"
         * });
         * ```
         */
        then<TResult1 = T, TResult2 = never>(onResolved?: ResolvedPromiseHandler<T, TResult1>, onRejected?: RejectedPromiseHandler<TResult2>): IPromise<TResult1 | TResult2>;
        /**
         * Attaches callbacks for the resolution and/or rejection of the Promise.
         * @param onResolved - The callback to execute when the Promise is resolved.
         * @param onRejected - The callback to execute when the Promise is rejected.
         * @returns A Promise for the completion of which ever callback is executed.
         * @example
         * ```ts
         * const promise1 = createPromise((resolve, reject) => {
         *   resolve('Success!');
         * });
         *
         * promise1.then((value) => {
         *   console.log(value);
         *   // expected output: "Success!"
         * });
         * ```
         */
        then<TResult1 = T, TResult2 = never>(onResolved?: ResolvedPromiseHandler<T, TResult1>, onRejected?: RejectedPromiseHandler<TResult2>): PromiseLike<TResult1 | TResult2>;
        /**
         * Attaches callbacks for the resolution and/or rejection of the Promise.
         * @param onResolved - The callback to execute when the Promise is resolved.
         * @param onRejected - The callback to execute when the Promise is rejected.
         * @returns A Promise for the completion of which ever callback is executed.
         * @example
         * ```ts
         * const promise1 = createPromise((resolve, reject) => {
         *   resolve('Success!');
         * });
         *
         * promise1.then((value) => {
         *   console.log(value);
         *   // expected output: "Success!"
         * });
         * ```
         */
        then<TResult1 = T, TResult2 = never>(onResolved?: ResolvedPromiseHandler<T, TResult1>, onRejected?: RejectedPromiseHandler<TResult2>): IPromise<TResult1 | TResult2>;
        /**
         * Attaches a callback for only the rejection of the Promise.
         * @param onRejected - The callback to execute when the Promise is rejected.
         * @returns A Promise for the completion of the callback.
         * @example
         * ```ts
         * const promise1 = createPromise((resolve, reject) => {
         *   throw 'Uh-oh!';
         * });
         *
         * promise1.catch((error) => {
         *   console.error(error);
         * });
         * // expected output: Uh-oh!
         * ```
         */
        catch<TResult = never>(onRejected?: ((reason: any) => TResult | IPromise<TResult>) | undefined | null): IPromise<T | TResult>;
        /**
         * Attaches a callback for only the rejection of the Promise.
         * @param onRejected - The callback to execute when the Promise is rejected.
         * @returns A Promise for the completion of the callback.
         * @example
         * ```ts
         * const promise1 = createPromise((resolve, reject) => {
         *   throw 'Uh-oh!';
         * });
         *
         * promise1.catch((error) => {
         *   console.error(error);
         * });
         * // expected output: Uh-oh!
         * ```
         */
        catch<TResult = never>(onRejected?: ((reason: any) => TResult | IPromise<TResult>) | undefined | null): PromiseLike<T | TResult>;
        /**
         * Attaches a callback for only the rejection of the Promise.
         * @param onRejected - The callback to execute when the Promise is rejected.
         * @returns A Promise for the completion of the callback.
         * @example
         * ```ts
         * const promise1 = createPromise((resolve, reject) => {
         *   throw 'Uh-oh!';
         * });
         *
         * promise1.catch((error) => {
         *   console.error(error);
         * });
         * // expected output: Uh-oh!
         * ```
         */
        catch<TResult = never>(onRejected?: ((reason: any) => TResult | IPromise<TResult>) | undefined | null): IPromise<T | TResult>;
        /**
         * Attaches a callback that is invoked when the Promise is settled (fulfilled or rejected). The
         * resolved value cannot be modified from the callback.
         * @param onfinally - The callback to execute when the Promise is settled (fulfilled or rejected).
         * @returns A Promise for the completion of the callback.
         * @example
         * ```ts
         * function doFunction() {
         *   return createPromise((resolve, reject) => {
         *     if (Math.random() > 0.5) {
         *       resolve('Function has completed');
         *     } else {
         *       reject(new Error('Function failed to process'));
         *     }
         *   });
         * }
         *
         * doFunction().then((data) => {
         *     console.log(data);
         * }).catch((err) => {
         *     console.error(err);
         * }).finally(() => {
         *     console.log('Function processing completed');
         * });
         * ```
         */
        finally(onfinally?: FinallyPromiseHandler): IPromise<T>;
    }

    /**
     * The IPropertyStorageOverride interface provides a custom interface for storing internal SDK properties - otherwise they are
     * stored as cookies.
     * You need this interface when you intend to run auto collection for common properties, or when you log a session in
     * a non browser environment.
     */
    interface IPropertyStorageOverride {
        /**
         * A function for passing key value pairs to be stored.
         * @param key   - The key for the key value pair.
         * @param value - The value for the key value pair.
         */
        setProperty: (key: string, value: string) => void;
        /**
         * A function that gets a value for a given key.
         * @param key - The key for which the value must be fetched.
         */
        getProperty: (key: string) => string;
    }

    /**
     * Provides an OpenTelemetry compatible Interface for the Open Telemetry Sdk-Trace-Base (1.8.0 and 2.0.0) ReadableSpan type.
     *
     * The IReadableSpan interface is used to represent a span that can be read and exported, while the OpenTelemetry
     * specification defines a ReadableSpan as a Span that has been ended and is ready to be exported. By default all
     * spans created by this library implement the IReadableSpan interface which also extends the {@link IOTelSpan} interface.
     *
     * This interface is defined to provide compatibility with exporters defined by the OpenTelemetry Trace SDK.
     * @since 3.4.0
     */
    interface IReadableSpan extends IOTelSpan {
        /**
         * The span's unique identifier.
         */
        readonly name: string;
        /**
         * Identifies the type (or kind) that this span is representing.
         */
        readonly kind: OTelSpanKind;
        readonly spanContext: () => IDistributedTraceContext;
        readonly parentSpanId?: string;
        readonly parentSpanContext?: IDistributedTraceContext;
        readonly startTime: IOTelHrTime;
        readonly endTime: IOTelHrTime;
        readonly status: IOTelSpanStatus;
        /**
         * Provides a snapshot of the span's attributes at the time this span was ended.
         * @returns A read-only snapshot of the span's attributes
         * @remarks
         * It is recommended that you only access this property sparingly due to the
         * performance cost of taking a snapshot of all attributes.
         */
        readonly attributes: IOTelAttributes;
        readonly duration: IOTelHrTime;
        readonly ended: boolean;
        readonly droppedAttributesCount: number;
    }

    interface _IRegisteredEvents {
        name: string;
        handler: any;
    }

    interface IResponseError {
        readonly index: number;
        readonly statusCode: number;
        readonly message: string;
    }

    /**
     * Checks if the type of value is an Array.
     *
     * @function
     * @group Type Identity
     * @group Array
     * @param arg - Value to be checked.
     * @return True if the value is a Array, false otherwise.
     * @example
     * ```ts
     * import { isArray, isObject } from "@nevware21/ts-utils";
     *
     * function performAction(value: any) {
     *     if (isArray(value) || isObject(value)) {
     *         // Do something
     *     } else {
     *         // Do something else
     *     }
     * }
     * ```
     */
    const isArray: <T = any>(arg: any) => arg is Array<T>;

    function isArrayValid(value: any[]): boolean;

    /**
     * Checks if HTML5 Beacons are supported in the current environment. There is a side effect (for testing)
     * when `useCached` is set to `false`, it will reset the cached value causing all future calls to
     * use the new re-evaluated value for all future calls.
     * @param useCached - [Optional] used for testing to bypass the cached lookup, when `true` this will
     * cause the cached global to be reset.
     * @returns True if supported, false otherwise.
     */
    function isBeaconsSupported(useCached?: boolean): boolean;

    /**
     * Checks if the type of value is a boolean.
     * @function
     * @group Type Identity
     * @param value - Value to be checked.
     * @return True if the value is a boolean, false otherwise.
     */
    const isBoolean: (value: any) => value is boolean;

    /**
     * Helper to identify whether we are running in a chromium based browser environment
     */
    function isChromium(): boolean;

    /**
     * Check if an object is of type Date
     * @function
     * @group Type Identity
     * @example
     * ```ts
     * import { isDate } from "@nevware21/ts-utils";
     *
     * let _theDate = null;
     *
     * function getSetDate(newDate?: any) {
     *     _theDate = isDate(newDate) ? newDate : new Date();
     *
     *     return _theDate;
     * }
     * ```
     */
    const isDate: (value: any) => value is Date;

    /**
     * Configuration for SDK Stats periodic reporting.
     */
    interface ISdkStatsConfig {
        /**
         * Flush interval in ms.
         * @defaultValue 900000 (15 minutes)
         */
        int?: number;
    }

    /**
     * Checks if document object is available
     */
    const isDocumentObjectAvailable: boolean;

    /**
     * internal interface
     * Define functions when xhr/xdr/fetch requests are successfully returned. If they are not defined, oncomplete with be called instead
     * @internal for internal use only
     */
    interface _ISenderOnComplete {
        /**
         * defined xdr onload function to handle response
         * @param dxr - xdr request object
         * @param oncomplete - oncomplete function
         * @since version after 3.1.0
         */
        xdrOnComplete?(xdr: IXDomainRequest, onComplete: OnCompleteCallback, payload?: IPayloadData): void;
        /**
         * defined fetch on complete function to handle response
         * @param response - response object
         * @param onComplete - oncomplete function
         * @param resValue - response.text().value
         * @since version after 3.1.0
         */
        fetchOnComplete?(response: Response, onComplete: OnCompleteCallback, resValue?: string, payload?: IPayloadData): void;
        /**
         * defined xhr onreadystatechange function to handle response
         * @param request - request object
         * @param oncomplete - oncomplete function
         * @since version after 3.1.0
         */
        xhrOnComplete?(request: XMLHttpRequest, onComplete: OnCompleteCallback, payload?: IPayloadData): void;
        /**
         * Define functions during beacon can not send payload after first attempt. If not defined, will be apyload will be retried with fallback sender.
         * @param data - payload data
         * @param onComplete - oncomplete function
         * @param canSend - can the current data sent by beacon sender
         * @since version after 3.1.0
         */
        beaconOnRetry?(data: IPayloadData, onComplete: OnCompleteCallback, canSend: (payload: IPayloadData, oncomplete: OnCompleteCallback, sync?: boolean) => boolean): void;
    }

    /**
     * Internal interface for SendPostMnager
     * @internal for internal use only
     */
    interface _ISendPostMgrConfig {
        /**
         * Enable the sender interface to return a promise
         * Note: Enabling this may cause unhandled promise rejection errors to occur if you do not listen and handle any rejection response,
         * Defaults to false
         * @since version after 3.1.0
         */
        enableSendPromise?: boolean;
        /**
         * Identifies if the sender is 1ds post channel
         * Default is false
         * @since version after 3.1.0
         */
        isOneDs?: boolean;
        /**
         * Identify if Credentials should be disabled for 1ds post channel, application insights sender will igore this config
         * Default is false
         * @since version after 3.1.0
         */
        disableCredentials?: boolean;
        /**
         * Identifies if `XMLHttpRequest` or `XDomainRequest` (for IE version before 9) should be used
         * Default: false
         * @since 3.1.1
         */
        disableXhr?: boolean;
        /**
         * Is beacon disabled during async sending
         * Default: false
         * @since version after 3.1.0
         */
        disableBeacon?: boolean;
        /**
         * Is beacon disabled during sync sending
         * Default: false
         * @since version after 3.1.0
         */
        disableBeaconSync?: boolean;
        /**
         * Is FetchKeepAlive disabled during sync sending
         * Default: false
         * @since version after 3.1.0
         */
        disableFetchKeepAlive?: boolean;
        /**
         * Identifies functions when xhr/xdr/fetch requests are successfully returned. If they are not defined, oncomplete with be called instead
         * @since version after 3.1.0
         */
        senderOnCompleteCallBack?: _ISenderOnComplete;
        /**
         * time wrapper to handle payload timeout
         * this is for 1ds post channel only
         * Default: null
         * @since version after 3.1.0
         */
        timeWrapper?: _ITimeoutOverrideWrapper;
        /**
         * [Optional] flag to indicate whether the sendBeacon and fetch (with keep-alive flag) should add the "NoResponseBody" query string
         * value to indicate that the server should return a 204 for successful requests. Defaults to true
         * this is for 1ds post channel only
         * Default: true
         * @since version after 3.1.0
         */
        addNoResponse?: boolean;
        /**
         * [Optional] Specify whether cross-site Access-Control fetch requests should include credentials such as cookies,
         * authentication headers, or TLS client certificates.
         *
         * Possible values:
         * - "omit": never send credentials in the request or include credentials in the response.
         * - "include": always include credentials, even cross-origin.
         * - "same-origin": only send and include credentials for same-origin requests.
         *
         * If not set, the default value will be "include".
         *
         * For more information, refer to:
         * - [Fetch API - Using Fetch](https://developer.mozilla.org/en-US/docs/Web/API/Fetch_API/Using_Fetch#including_credentials)
         * @since version after 3.3.1
         */
        fetchCredentials?: RequestCredentials;
    }

    /**
     * Checks if the type of value is a Error object.
     * @function
     * @group Type Identity
     * @group Error
     * @param value - Value to be checked.
     * @return True if the value is a Error, false otherwise.
     */
    const isError: (value: any) => value is Error;

    /**
     * Checks if the feature is enabled on not. If the feature is not defined, it will return the default state if provided or undefined.
     * If the feature is defined, it will check the mode and return true if the mode is enable or false if the mode is disable.
     * @param feature - The feature name to check
     * @param cfg - The configuration object to check the feature state against
     * @param sdkDefaultState - Optional default state to return if the feature is not defined
     * @returns True if the feature is enabled, false if the feature is disabled, or undefined if the feature is not defined and no default state is provided.
     */
    function isFeatureEnabled<T extends IConfiguration = IConfiguration>(feature?: string, cfg?: T, sdkDefaultState?: boolean): boolean | undefined;

    /**
     * Checks if the Fetch API is supported in the current environment.
     * @param withKeepAlive - [Optional] If True, check if fetch is available and it supports the keepalive feature, otherwise only check if fetch is supported
     * @returns True if supported, otherwise false
     */
    function isFetchSupported(withKeepAlive?: boolean): boolean;

    /**
     * Checks to see if the past value is a function value
     * @function
     * @group Type Identity
     * @param value - The value to check
     * @returns
     * @example
     * ```ts
     * function myFunction() { }
     * isFunction(null);            // false
     * isFunction(undefined);       // false
     * isFunction("null");          // false
     * isFunction("undefined");     // false
     * isFunction("1");             // false
     * isFunction("aa");            // false
     * isFunction(new Date());      // false
     * isFunction(1);               // false
     * isFunction("");              // false
     * isFunction(myFunction);      // true
     * isFunction([]);              // false
     * isFunction(new Array(1));    // false
     * ```
     */
    const isFunction: (value: any) => value is Function;

    /**
     * Check to see if the value is \> 0
     * @param value - The value to check
     * @returns true if \> 0 otherwise false
     */
    function isGreaterThanZero(value: number): boolean;

    /**
     * Identifies whether the current environment appears to be IE
     */
    function isIE(): boolean;

    /**
     * Checks if the value is a valid EventLatency.
     * @param value - The value that needs to be checked.
     * @returns True if the value is in AWTEventLatency, false otherwise.
     */
    function isLatency(value: EventLatency | undefined): boolean;

    /**
     * Checks if the type of value does not evaluate to true value, handling some special
     * case usages of Boolean(true/false) and new Boolean(true/false).
     * @group Value Check
     * @param value - Value to be checked.
     * @return True if the value is not truthy, false otherwise.
     */
    function isNotTruthy(value: any): boolean;

    /**
     * Checks if the provided value is null, undefined or contains the string value of "undefined".
     * @group Type Identity
     * @group Value Check
     * @param value - The value to check
     * @returns `true` if the value is `null` or `undefined`
     * @example
     * ```ts
     * isNullOrUndefined(null);         // true
     * isNullOrUndefined(undefined);    // true
     * isNullOrUndefined("undefined");  // true
     *
     * let value = null;
     * isNullOrUndefined(value);        // true
     * let value = undefined;
     * isNullOrUndefined(value);        // true
     *
     * isNullOrUndefined("");           // false
     * isNullOrUndefined(0);            // false
     * isNullOrUndefined(new Date());   // false
     * isNullOrUndefined(true);         // false
     * isNullOrUndefined(false);        // false
     * ```
     */
    function isNullOrUndefined(value: any): boolean;

    /**
     * Checks if the type of value is a number.
     * @function
     * @group Type Identity
     * @param value - Value to be checked.
     * @return True if the value is a number, false otherwise.
     */
    const isNumber: (value: any) => value is number;

    /**
     * Checks to see if the past value is an object value
     * @function
     * @group Type Identity
     * @group Object
     * @typeParam T - The object type, defaults to any
     * @param value - The value to check
     * @returns
     */
    function isObject<T>(value: T): value is T;

    /**
     * Represents the execution scope for a span, combining the trace instance and the active span.
     * This interface is used as the context for executing functions within a span's scope.
     *
     * @since 3.4.0
     */
    interface ISpanScope<T extends ITraceHost = ITraceHost> {
        /**
         * The trace host (core or AISKU instance).
         * @since 3.4.0
         */
        readonly host: T;
        /**
         * The active span for this execution scope.
         * @since 3.4.0
         */
        readonly span: IReadableSpan;
        /**
         * The previously active span before this scope was created, if any.
         * @since 3.4.0
         */
        readonly prvSpan?: IReadableSpan;
        /**
         * Restores the previous active span in the trace instance.
         * @since 3.4.0
         */
        restore(): void;
    }

    /**
     * Returns whether the environment is reporting that we are running in a React Native Environment
     */
    function isReactNative(): boolean;

    /**
     * Is the parsed traceParent indicating that the trace is currently sampled.
     * @param value - The parsed traceParent value
     * @returns
     */
    function isSampledFlag(value: ITraceParent): boolean;

    /**
     * Checks to see if the past value is a string value
     * @function
     * @group Type Identity
     * @group String
     * @param value - The value to check
     * @returns
     * @example
     * ```ts
     * isString("");            // true
     * isString("null");        // true
     * isString("undefined");   // true
     * isString(String(""));    // true
     *
     * isString(null);          // false
     * isString(undefined);     // false
     * isString(0);             // false
     * ```
     */
    const isString: (value: any) => value is string;

    /**
     * The Interface which defines the InternalSdkStats manager, which is responsible for creating and
     * managing the InternalSdkStats instance.
     * @since 3.3.7
     */
    interface IStatsMgr {
        /**
         * If there is a manager instance available, this will identify if the manager is enabled or not.
         * @returns True if the manager is enabled, false otherwise.
         */
        readonly enabled: boolean;
        /**
         * Initialize and associate this manager with the provided core instance. The manager reads its
         * configuration directly from the single global config (`config.stats`) and gates itself behind
         * the SDK Stats feature flag, so any changes made via the CDN / dynamic config are picked up at
         * runtime.
         * @param core - The core instance to associate with this manager.
         * @param createStatsCore - Creates an isolated, initialized core for SDK Stats. The callback lets
         * each SKU select the appropriate channel and plugins without using the customer's pipeline.
         * @param featureName - The optional featureOptIn name used to gate the manager. Defaults to the
         * SDK Stats feature (`STATS_SDK_FEATURE`) which is enabled by default and can be opted-out via the
         * `featureOptIn` configuration.
         * @param useFeature - Optional feature operation throttle supplied by the SKU.
         * @returns The unload hook for the stats beat manager, which can be used to unload
         * and disable the manager. This may return null if the manager cannot be initialized.
         * @remarks This method should be called only once, and it may throw an error if called multiple times.
         */
        init: <CfgType extends IConfiguration = IConfiguration>(core: IAppInsightsCore<CfgType>, createStatsCore: CreateStatsCoreFn, featureName?: string, useFeature?: UseFeatureFn) => IUnloadHook | null;
        /**
         * Returns a new {@link IInternalSdkStats} instance for the current state which includes the endpoint.
         * This method should be called only after the manager has been initialized and the
         * {@link IInternalSdkStatsConfig} has been set, otherwise it will return null.
         * @param state - The current state of the stats beat manager.
         * @returns A new instance of the stats beat or null if the manager or the configuration does not support
         * the {@link IInternalSdkStatsState}.
         */
        newInst: (state: IInternalSdkStatsState) => IInternalSdkStats;
    }

    /**
     * Checks if the type of value evaluates to true value, handling some special
     * case usages of Boolean(true/false) and new Boolean(true/false).
     * @group Value Check
     * @param value - Value to be checked.
     * @return True if the value is not truthy, false otherwise.
     */
    function isTruthy(value: any): boolean;

    /**
     * Validate if the provided value object is of the expected type
     * @group Type Identity
     * @param value - The value to check
     * @param theType - The expected type name as a string
     * @returns `true` if the value matches the provided type
     */
    function isTypeof(value: any, theType: string): boolean;

    /**
     * Checks if Uint8Array are available in the current environment. Safari and Firefox along with
     * ReactNative are known to not support Uint8Array properly.
     * @returns True if available, false otherwise.
     */
    function isUint8ArrayAvailable(): boolean;

    /**
     * Checks if the provided value is undefined or contains the string value "undefined",
     * if you want to consider the string value as undefined see {@link isStrictUndefined}
     * @group Type Identity
     * @group Value Check
     * @param value - The value to check
     * @returns true if the value is undefined or "undefined", otherwise false
     * @example
     * ```ts
     * isUndefined(undefined);              // true
     * isUndefined("undefined");            // true
     *
     * isUndefined(null);                   // false
     * isUndefined("null");                 // false
     * isUndefined("1");                    // false
     * isUndefined("aa");                   // false
     * isUndefined(new Date());             // false
     * isUndefined(1);                      // false
     * isUndefined("");                     // false
     * isUndefined(_dummyFunction);         // false
     * isUndefined([]);                     // false
     * isUndefined(new Array(1));           // false
     * isUndefined(true);                   // false
     * isUndefined(false);                  // false
     * isUndefined("true");                 // false
     * isUndefined("false");                // false
     * isUndefined(new Boolean(true));      // false
     * isUndefined(new Boolean(false));     // false
     * isUndefined(new Boolean("true"));    // false
     * isUndefined(new Boolean("false"));   // false
     * isUndefined(Boolean(true));          // false
     * isUndefined(Boolean(false));         // false
     * isUndefined(Boolean("true"));        // false
     * isUndefined(Boolean("false"));       // false
     * isUndefined(new RegExp(""));         // false
     * isUndefined(new ArrayBuffer(0));     // false
     * isUndefined(new Error("Test Error"));// false
     * isUndefined(new TypeError("Test TypeError"));    // false
     * isUndefined(new TestError("Test TestError"));    // false
     * isUndefined(_dummyError());          // false
     * isUndefined(Promise.reject());       // false
     * isUndefined(Promise.resolve());      // false
     * isUndefined(new Promise(() => {}));  // false
     * isUndefined(_simplePromise());       // false
     * isUndefined(_simplePromiseLike());   // false
     * isUndefined(Object.create(null));    // false
     * isUndefined(polyObjCreate(null));    // false
     * ```
     */
    function isUndefined(value: any): boolean;

    /**
     * Is the provided W3c span id (aka. parent id) a valid string representation, it must be a 16-character
     * string of lowercase hexadecimal characters, for example, 00f067aa0ba902b7.
     * If all characters are zero (0000000000000000) this is considered an invalid value.
     * @param value - The W3c span id to be validated
     * @returns true if valid otherwise false
     */
    function isValidSpanId(value: string): boolean;

    /**
     * Is the provided W3c Trace Id a valid string representation, it must be a 32-character string
     * of lowercase hexadecimal characters for example, 4bf92f3577b34da6a3ce929d0e0e4736.
     * If all characters as zero (00000000000000000000000000000000) it will be considered an invalid value.
     * @param value - The W3c trace Id to be validated
     * @returns true if valid otherwise false
     */
    function isValidTraceId(value: string): boolean;

    /**
     * Validates that the provided ITraceParent instance conforms to the currently supported specifications
     * @param value - The parsed traceParent value
     * @returns
     */
    function isValidTraceParent(value: ITraceParent): boolean;

    /**
     * Checks if value is assigned to the given param.
     * @param value - The token from which the tenant id is to be extracted.
     * @returns True/false denoting if value is assigned to the param.
     */
    function isValueAssigned(value: any): boolean;

    function isValueKind(value: number | undefined): boolean;

    /**
     * Checks if window object is available
     */
    const isWindowObjectAvailable: boolean;

    /**
     * Checks if XMLHttpRequest is supported
     * @returns True if supported, otherwise false
     */
    function isXhrSupported(): boolean;

    interface ITelemetryInitializerContainer {
        /**
         * Add a telemetry processor to decorate or drop telemetry events.
         * @param telemetryInitializer - The Telemetry Initializer function
         * @returns - A ITelemetryInitializerHandler to enable the initializer to be removed
         */
        addTelemetryInitializer(telemetryInitializer: TelemetryInitializerFunction): ITelemetryInitializerHandler | void;
    }

    interface ITelemetryInitializerHandler extends ILegacyUnloadHook {
        remove(): void;
    }

    /**
     * Telemety item supported in Core
     */
    interface ITelemetryItem {
        /**
         * CommonSchema Version of this SDK
         */
        ver?: string;
        /**
         * Unique name of the telemetry item
         */
        name: string;
        /**
         * Timestamp when item was sent
         */
        time?: string;
        /**
         * Identifier of the resource that uniquely identifies which resource data is sent to
         */
        iKey?: string;
        /**
         * System context properties of the telemetry item, example: ip address, city etc
         */
        ext?: {
            [key: string]: any;
        };
        /**
         * System context property extensions that are not global (not in ctx)
         */
        tags?: Tags;
        /**
         * Custom data
         */
        data?: ICustomProperties;
        /**
         * Telemetry type used for part B
         */
        baseType?: string;
        /**
         * Based on schema for part B
         */
        baseData?: {
            [key: string]: any;
        };
    }

    /**
     * Configuration provided to SDK core
     */
    interface ITelemetryPlugin extends ITelemetryProcessor, IPlugin {
        /**
         * Set next extension for telemetry processing, this is now optional as plugins should use the
         * processNext() function of the passed IProcessTelemetryContext instead. It is being kept for
         * now for backward compatibility only.
         * @deprecated - Use processNext() function of the passed IProcessTelemetryContext instead
         */
        setNextPlugin?: (next: ITelemetryPlugin | ITelemetryPluginChain) => void;
        /**
         * Priority of the extension
         */
        readonly priority: number;
    }

    /**
     * Configuration provided to SDK core
     */
    interface ITelemetryPluginChain extends ITelemetryProcessor {
        /**
         * Returns the underlying plugin that is being proxied for the processTelemetry call
         */
        getPlugin: () => ITelemetryPlugin;
        /**
         * Returns the next plugin
         */
        getNext: () => ITelemetryPluginChain;
        /**
         * This plugin is being unloaded and should remove any hooked events and cleanup any global/scoped values, after this
         * call the plugin will be removed from the telemetry processing chain and will no longer receive any events..
         * @param unloadCtx - The unload context to use for this call.
         * @param unloadState - The details of the unload operation
         */
        unload?: (unloadCtx: IProcessTelemetryUnloadContext, unloadState: ITelemetryUnloadState) => void;
    }

    interface ITelemetryProcessor {
        /**
         * Call back for telemetry processing before it it is sent
         * @param env - This is the current event being reported
         * @param itemCtx - This is the context for the current request, ITelemetryPlugin instances
         * can optionally use this to access the current core instance or define / pass additional information
         * to later plugins (vs appending items to the telemetry item)
         */
        processTelemetry: (env: ITelemetryItem, itemCtx?: IProcessTelemetryContext) => void;
        /**
         * The the plugin should re-evaluate configuration and update any cached configuration settings or
         * plugins. If implemented this method will be called whenever a plugin is added or removed and if
         * the configuration has bee updated.
         * @param updateCtx - This is the context that should be used during updating.
         * @param updateState - The details / state of the update process, it holds details like the current and previous configuration.
         * @returns boolean - true if the plugin has or will call updateCtx.processNext(), this allows the plugin to perform any asynchronous operations.
         */
        update?: (updateCtx: IProcessTelemetryUpdateContext, updateState: ITelemetryUpdateState) => void | boolean;
    }

    interface ITelemetryUnloadState {
        reason: TelemetryUnloadReason;
        isAsync: boolean;
        flushComplete?: boolean;
    }

    interface ITelemetryUpdateState {
        /**
         * Identifies the reason for the update notification, this is a bitwise numeric value
         */
        reason: TelemetryUpdateReason;
        /**
         * This is a new active configuration that should be used
         */
        cfg?: IConfiguration;
        /**
         * The detected changes
         */
        oldCfg?: IConfiguration;
        /**
         * If this is a configuration update this was the previous configuration that was used
         */
        newConfig?: IConfiguration;
        /**
         * Was the new config requested to be merged with the existing config
         */
        merge?: boolean;
        /**
         * This holds a collection of plugins that have been added (if the reason identifies that one or more plugins have been added)
         */
        added?: IPlugin[];
        /**
         * This holds a collection of plugins that have been removed (if the reason identifies that one or more plugins have been removed)
         */
        removed?: IPlugin[];
    }

    /**
     * Identifies throttle result
     */
    interface IThrottleResult {
        /**
         * Identifies if items are sent
         */
        isThrottled: boolean;
        /**
         * Identifies numbers of items are sent
         * if isThrottled is false, it will be set to 0
         */
        throttleNum: number;
    }

    /**
     * Internal interface
     * Simple internal timeout wrapper
     * @internal
     * @since version after 3.1.0
     */
    interface _ITimeoutOverrideWrapper {
        set: (callback: (...args: any[]) => void, ms: number, ...args: any[]) => ITimerHandler;
    }

    /**
     * A Timer handler which is returned from {@link scheduleTimeout} which contains functions to
     * cancel or restart (refresh) the timeout function.
     *
     * @since 0.4.4
     * @group Timer
     */
    interface ITimerHandler {
        /**
         * Cancels a timeout that was previously scheduled, after calling this function any previously
         * scheduled timer will not execute.
         * @example
         * ```ts
         * let theTimer = scheduleTimeout(...);
         * theTimer.cancel();
         * ```
         */
        cancel(): void;
        /**
         * Reschedules the timer to call its callback at the previously specified duration
         * adjusted to the current time. This is useful for refreshing a timer without allocating
         * a new JavaScript object.
         *
         * Using this on a timer that has already called its callback will reactivate the timer.
         * Calling on a timer that has not yet executed will just reschedule the current timer.
         * @example
         * ```ts
         * let theTimer = scheduleTimeout(...);
         * // The timer will be restarted (if already executed) or rescheduled (if it has not yet executed)
         * theTimer.refresh();
         * ```
         */
        refresh(): ITimerHandler;
        /**
         * When called, requests that the event loop not exit so long when the ITimerHandler is active.
         * Calling timer.ref() multiple times will have no effect. By default, all ITimerHandler objects
         * will create "ref'ed" instances, making it normally unnecessary to call timer.ref() unless
         * timer.unref() had been called previously.
         * @since 0.7.0
         * @returns the ITimerHandler instance
         * @example
         * ```ts
         * let theTimer = createTimeout(...);
         *
         * // Make sure the timer is referenced (the default) so that the runtime (Node) does not terminate
         * // if there is a waiting referenced timer.
         * theTimer.ref();
         * ```
         */
        ref(): this;
        /**
         * When called, the any active ITimerHandler instance will not require the event loop to remain
         * active (Node.js). If there is no other activity keeping the event loop running, the process may
         * exit before the ITimerHandler instance callback is invoked. Calling timer.unref() multiple times
         * will have no effect.
         * @since 0.7.0
         * @returns the ITimerHandler instance
         * @example
         * ```ts
         * let theTimer = createTimeout(...);
         *
         * // Unreference the timer so that the runtime (Node) may terminate if nothing else is running.
         * theTimer.unref();
         * ```
         */
        unref(): this;
        /**
         * If true, any running referenced `ITimerHandler` instance will keep the Node.js event loop active.
         * @since 0.7.0
         * @example
         * ```ts
         * let theTimer = createTimeout(...);
         *
         * // Unreference the timer so that the runtime (Node) may terminate if nothing else is running.
         * theTimer.unref();
         * let hasRef = theTimer.hasRef(); // false
         *
         * theTimer.ref();
         * hasRef = theTimer.hasRef(); // true
         * ```
         */
        hasRef(): boolean;
        /**
         * Gets or Sets a flag indicating if the underlying timer is currently enabled and running.
         * Setting the enabled flag to the same as it's current value has no effect, setting to `true`
         * when already `true` will not {@link ITimerHandler.refresh | refresh}() the timer.
         * And setting to `false` will {@link ITimerHandler.cancel | cancel}() the timer.
         * @since 0.8.1
         * @example
         * ```ts
         * let theTimer = createTimeout(...);
         *
         * // Check if enabled
         * theTimer.enabled; // false
         *
         * // Start the timer
         * theTimer.enabled = true;     // Same as calling refresh()
         * theTimer.enabled; //true
         *
         * // Has no effect as it's already running
         * theTimer.enabled = true;
         *
         * // Will refresh / restart the time
         * theTimer.refresh()
         *
         * let theTimer = scheduleTimeout(...);
         *
         * // Check if enabled
         * theTimer.enabled; // true
         * ```
         */
        enabled: boolean;
    }

    /**
     * ITraceApi provides an interface definition which is simular to the OpenTelemetry TraceAPI
     */
    interface ITraceApi {
        /**
         * Returns a Tracer, creating one if one with the given name and version
         * if one has not already created.
         *
         * @param name - The name of the tracer or instrumentation library.
         * @param version - The version of the tracer or instrumentation library.
         * @param options - The options of the tracer or instrumentation library.
         * @returns Tracer A Tracer with the given name and version
         */
        getTracer(name: string, version?: string, options?: IOTelTracerOptions): IOTelTracer;
        /**
         * Wrap the given {@link IDistributedTraceContext} in a new non-recording {@link IReadableSpan}
         *
         * @param spanContext - The {@link IDistributedTraceContext} to be wrapped
         * @returns a new non-recording {@link IReadableSpan} with the provided context
         */
        wrapSpanContext(spanContext: IDistributedTraceContext | IDistributedTraceInit | IOTelSpanContext): IReadableSpan;
        /**
         * Returns true if this {@link IDistributedTraceContext} is valid.
         * @return true if this {@link IDistributedTraceContext} is valid.
         */
        isSpanContextValid(spanContext: IDistributedTraceContext | IDistributedTraceInit | IOTelSpanContext): boolean;
        /**
         * Gets the span from the current context, if one exists.
         */
        getActiveSpan(): IReadableSpan | undefined | null;
        /**
         * Set or clear the current active span.
         * @param span - The span to set as the active span, or null/undefined to clear the active span.
         * @return An ISpanScope instance returned by the host, or void if there is no defined host.
         */
        setActiveSpan(span: IReadableSpan | undefined | null): ISpanScope | undefined | null;
    }

    /**
     * Configuration interface for OpenTelemetry compatible tracing functionality.
     * This interface contains all the settings that control how traces are created,
     * processed, and managed within the OpenTelemetry system.
     *
     * @example
     * ```typescript
     * const traceCfg: ITraceCfg = {
     *   serviceName: "my-service",
     *   generalLimits: {
     *     attributeCountLimit: 128,
     *     attributeValueLengthLimit: 4096
     *   },
     *   spanLimits: {
     *     attributeCountLimit: 128,
     *     linkCountLimit: 128,
     *     eventCountLimit: 128
     *   }
     * };
     * ```
     *
     * @since 3.4.0
     */
    interface ITraceCfg {
        /**
         * Global attribute limits that apply to all telemetry items.
         * These limits help prevent excessive memory usage and ensure consistent
         * behavior across different telemetry types.
         *
         * @remarks
         * These limits are inherited by more specific configurations unless overridden.
         * For example, spans will use these limits unless `spanLimits` specifies different values.
         */
        generalLimits?: IOTelAttributeLimits;
        /**
         * The name of the service generating telemetry data.
         * This name will be included in all telemetry items as a resource attribute.
         *
         * @remarks
         * The service name is crucial for identifying and filtering telemetry data
         * in observability systems. It should be consistent across all instances
         * of the same service.
         *
         * @example
         * ```typescript
         * serviceName: "user-authentication-service"
         * ```
         */
        serviceName?: string;
        /**
         * A flag that indicates whether the tracing (creating of a "trace" event) should be suppressed
         * when a {@link IOTelSpan} ends and the span {@link IOTelSpan#isRecording | isRecording} is true.
         * This value is also inherited by spans when they are created.
         */
        suppressTracing?: boolean;
    }

    /**
     * Interface for OpenTelemetry trace operations.
     * This interface provides span creation, context management, and trace provider operations
     * that are common across different SDK implementations (Core, AISKU, etc.).
     *
     * @since 3.4.0
     */
    interface ITraceHost<CfgType extends IConfiguration = IConfiguration> {
        readonly config: CfgType;
        /**
         * Gets the current distributed trace active context for this instance
         * @param createNew - Optional flag to create a new instance if one doesn't currently exist, defaults to true. By default this
         * will use any located parent as defined by the {@link IConfiguration.traceHdrMode} configuration for each new instance created.
         */
        getTraceCtx(createNew?: boolean): IDistributedTraceContext | null;
        /**
         * Sets the current distributed trace context for this instance if available
         */
        setTraceCtx(newTraceCtx: IDistributedTraceContext | null | undefined): void;
        /**
         * Start a new span with the given name and optional parent context.
         *
         * Note: This method only creates and returns the span. It does not automatically
         * set the span as the active trace context. Context management should be handled
         * separately using setTraceCtx() if needed.
         *
         * @param name - The name of the span
         * @param options - Options for creating the span (kind, attributes, startTime)
         * @param parent - Optional parent context. If not provided, uses the current active trace context
         * @returns A new span instance, or null if no trace provider is available
         * @since 3.4.0
         *
         * @see {@link IReadableSpan} - Interface for individual spans
         * @see {@link IOTelSpanOptions} - Configuration options for span creation
         */
        startSpan(name: string, options?: IOTelSpanOptions, parent?: IDistributedTraceContext): IReadableSpan | null;
        /**
         * Return the current active span, if no trace provider is available null will be returned
         * but when a trace provider is available a span instance will always be returned, even if
         * there is no active span (in which case a non-recording span will be returned).
         * @param createNew - Optional flag to create a non-recording span if no active span exists, defaults to true.
         * When false, returns the existing active span or null without creating a non-recording span, which can improve
         * performance when only checking if an active span exists.
         * @returns The current active span or null if no trace provider is available or if createNew is false and no active span exists
         * @since 3.4.0
         */
        getActiveSpan(createNew?: boolean): IReadableSpan | null;
        /**
         * Set the current Active Span, if no trace provider is available the span will be not be set as the active span.
         * @param span - The span to set as the active span
         * @returns An ISpanScope instance that provides the current scope, the span will always be the span passed in
         * even when no trace provider is available
         * @since 3.4.0
         */
        setActiveSpan(span: IReadableSpan): ISpanScope;
        /**
         * Get the current trace provider.
         *
         * @returns The current trace provider, or null if none is set
         * @since 3.4.0
         */
        getTraceProvider(): ITraceProvider | null;
    }

    /**
     * This interface represents the components of a W3C traceparent header
     */
    interface ITraceParent {
        /**
         * The version of the definition, this MUST be a string with a length of 2 and only contain lowercase
         * hexadecimal characters. A value of 'ff' is considered to be an invalid version.
         */
        version: string;
        /**
         * This is the ID of the whole trace forest and is used to uniquely identify a distributed trace
         * through a system. It is represented as a 32-character string of lowercase hexadecimal characters,
         * for example, 4bf92f3577b34da6a3ce929d0e0e4736.
         * All characters as zero (00000000000000000000000000000000) is considered an invalid value.
         */
        traceId: string;
        /**
         * This is the ID of the current request as known by the caller (in some tracing systems, this is also
         * known as the parent-id, where a span is the execution of a client request). It is represented as an
         * 16-character string of lowercase hexadecimal characters, for example, 00f067aa0ba902b7.
         * All bytes as zero (0000000000000000) is considered an invalid value.
         */
        spanId: string;
        /**
         * An 8-bit value of flags that controls tracing such as sampling, trace level, etc. These flags are
         * recommendations given by the caller rather than strict rules to follow.
         * As this is a bit field, you cannot interpret flags by decoding the hex value and looking at the resulting
         * number. For example, a flag 00000001 could be encoded as 01 in hex, or 09 in hex if present with the flag
         * 00001000. A common mistake in bit fields is forgetting to mask when interpreting flags.
         */
        traceFlags: number;
    }

    /**
     * A trace provider interface that enables different SKUs to provide their own
     * span implementations while being managed by the core SDK.
     *
     * This follows the OpenTelemetry TraceProvider pattern, allowing the core to
     * delegate span creation to the appropriate implementation based on the SDK variant.
     *
     * @since 3.4.0
     */
    interface ITraceProvider {
        /**
         * The OpenTelemetry API instance associated with this trace provider.
         * This provides access to the tracer provider and other OpenTelemetry functionality.
         * @since 3.4.0
         */
        readonly api: IOTelApi;
        /**
         * Creates a new span with the given name and options.
         *
         * @param name - The name of the span
         * @param options - Options for creating the span (kind, attributes, startTime)
         * @param parent - Optional parent context. If not provided, uses the current active trace context
         * @returns A new span instance specific to this provider's implementation
         * @since 3.4.0
         */
        createSpan(name: string, options?: IOTelSpanOptions, parent?: IDistributedTraceContext): IReadableSpan;
        /**
         * Gets the provider identifier for debugging and logging purposes.
         * @returns A string identifying this trace provider implementation
         * @since 3.4.0
         */
        getProviderId(): string;
        /**
         * Determines if this provider is available and ready to create spans.
         * @returns true if the provider can create spans, false otherwise
         * @since 3.4.0
         */
        isAvailable(): boolean;
    }

    interface IUnloadableComponent {
        /**
         * Teardown / Unload hook to allow implementations to perform some additional unload operations before the BaseTelemetryPlugin
         * finishes it's removal.
         * @param unloadCtx - This is the context that should be used during unloading.
         * @param unloadState - The details / state of the unload process, it holds details like whether it should be unloaded synchronously or asynchronously and the reason for the unload.
         * @param asyncCallback - An optional callback that the plugin must call if it returns true to inform the caller that it has completed any async unload/teardown operations.
         * @returns boolean - true if the plugin has or will call asyncCallback, this allows the plugin to perform any asynchronous operations.
         */
        _doUnload?: (unloadCtx?: IProcessTelemetryUnloadContext, unloadState?: ITelemetryUnloadState, asyncCallback?: () => void) => void | boolean;
    }

    interface IUnloadHandlerContainer {
        add: (handler: UnloadHandler) => void;
        run: (itemCtx: IProcessTelemetryUnloadContext, unloadState: ITelemetryUnloadState) => void;
    }

    /**
     * An interface which provides automatic removal during unloading of the component
     */
    interface IUnloadHook {
        /**
         * Self remove the referenced component
         */
        rm: () => void;
    }

    /**
     * Interface which identifiesAdd this hook so that it is automatically removed during unloading
     * @param hooks - The single hook or an array of IInstrumentHook objects
     */
    interface IUnloadHookContainer {
        add: (hooks: IUnloadHook | IUnloadHook[] | Iterator<IUnloadHook> | ILegacyUnloadHook | ILegacyUnloadHook[] | Iterator<ILegacyUnloadHook>) => void;
        run: (logger?: IDiagnosticLogger) => void;
    }

    /**
     * This interface is used during the serialization of events into envelope (serialized object) which is sent to the services, the format is defined via the
     * [Common Schema 4.0](https://aka.ms/CommonSchema) specification. The path and field names used are based on how the data is serialized
     * to the service (CS 4.0 location) and not specifically the location on the event object you pass into the track methods (unless they are the same).
     */
    interface IValueSanitizer {
        /**
         * Add a value sanitizer as a fallback sanitizer if this sanitizer can't handle the path/name.
         */
        addSanitizer: (sanitizer: IValueSanitizer) => void;
        /**
         * Adds a field sanitizer to the evaluation list
         */
        addFieldSanitizer: (fieldSanitizer: IFieldValueSanitizerProvider) => void;
        /**
         * Removes the value sanitizer as a fallback sanitizer if this sanitizer can't handle the path/name if present.
         */
        rmSanitizer: (theSanitizer: IValueSanitizer) => void;
        /**
         * Removes the field sanitizer to the evaluation list if present
         */
        rmFieldSanitizer: (theFieldSanitizer: IFieldValueSanitizerProvider) => void;
        /**
         * Does this field value sanitizer handle this path / field combination
         * @param path - The field path
         * @param name - The name of the field
         */
        handleField: (path: string, name: string) => boolean;
        /**
         * Sanitizes the value. It checks the that the property name and value are valid. It also
         * checks/populates the correct type and pii of the property value.
         * @param path - The root path of the property
         * @param name - The property name.
         * @param value - The property value or an IEventProperty containing value, type ,pii and customer content.
         * @param stringifyObjects - If supplied tells the sanitizer that it should JSON stringify() objects
         * @returns IEventProperty containing valid name, value, pii and type or null if invalid.
         */
        value: (path: string, name: string, value: FieldValueSanitizerTypes, stringifyObjects?: boolean) => IEventProperty | null;
        /**
         * Sanitizes the Property. It checks the that the property name and value are valid. It also
         * checks/populates the correct type and pii of the property value.
         * @param path - The root path of the property
         * @param name - The property name.
         * @param property - The property value or an IEventProperty containing value, type ,pii and customer content.
         * @param stringifyObjects - If supplied tells the sanitizer that it should JSON stringify() objects
         * @returns IEventProperty containing valid name, value, pii and type or null if invalid.
         */
        property: (path: string, name: string, property: IEventProperty, stringifyObjects?: boolean) => IEventProperty | null;
    }

    /**
     * Represents a mutable [W3C trace state list](https://www.w3.org/TR/trace-context/#tracestate-header), this is a
     * list of key/value pairs that are used to pass trace state information between different tracing systems. The
     * list is ordered and the order is important as it determines the processing order.
     *
     * Importantly instances of this type are mutable, change made to an instance via {@link IW3cTraceState.set} or
     * {@link IW3cTraceState.del} will be reflected on the instance and any child instances that use it as a parent.
     * However, any parent instance associated with an instance will not be modified by operations on that particular
     * instance.
     *
     * @since 3.4.0
     */
    interface IW3cTraceState {
        /**
         * Returns a readonly array of the current keys associated with the trace state, keys are returned in the
         * required processing order and if this instance has a parent the keys from the parent will be included
         * unless they have been removed (deleted) from the child instance.
         * Once created any modifications to the parent will also be reflected in the child, this is different from
         * the OpenTelemetry implementation which creates a new instance for each call.
         * @returns A readonly array of the current keys associated with the trace state
         */
        readonly keys: string[];
        /**
         * Check if the trace state list is empty, meaning it has no keys or values.
         * This exists to allow for quick checks without needing to create a new array of keys.
         * @since 3.4.0
         * @returns true if the trace state list is empty, false otherwise
         */
        readonly isEmpty: boolean;
        /**
         * Get the value for the specified key that is associated with this instance, either directly or from the parent.
         * @param key - The key to lookup
         * @returns The value for the key, or undefined if not found
         */
        get(key: string): string | undefined;
        /**
         * Set the value for the specified key for this instance, returning its new location within the list.
         * - 0 is the front of the list
         * - -1 not set because the key/value pair is invalid
         * If the key already exists it will be removed from its current location and added to the front of the list. And
         * if the key was in the parent this will override the value inherited from the parent, more importantly it will
         * not modify the parent value.
         * @param key - The key to set
         * @param value - The value to set
         * @returns 0 if successful, -1 if not
         */
        set(key: string, value: string): number;
        /**
         * Delete the specified key from this instance, if the key was in the parent it will be removed (hidden) from
         * this instance but will still be available directly from the parent.
         * @param key - The key to delete
         */
        del(key: string): void;
        /**
         * Format the trace state list into a strings where each string can be used as a header value.
         * This will return an empty array if the trace state list is empty.
         * @param maxHeaders - The maximum number of entries to include in the output, once the limit is reached no more entries will be included
         * @param maxKeys - The maximum number of keys to include in the output, once the limit is reached no more keys will be included
         * @param maxLen - The maximum length of each header value, once the limit is reached a new header value will be created
         * @returns An array of strings that can be used for the header values, if the trace state list is empty an empty array will be returned
         */
        hdrs(maxHeaders?: number, maxKeys?: number, maxLen?: number): string[];
        /**
         * Create a new instance of IW3cTraceState which is a child of this instance, meaning it will inherit the keys
         * and values from this instance but any changes made to the child will not affect this instance.
         * @returns A new instance of IW3cTraceState which is a child of this instance
         */
        child(): IW3cTraceState;
    }

    interface IWatchDetails<T = IConfiguration> {
        /**
         * The current config object
         */
        cfg: T;
        /**
         * Set the value against the provided config/name with the value, the property
         * will be converted to be dynamic (if not already) as long as the provided config
         * is already a tracked dynamic object.
         * @throws TypeError if the provided config is not a monitored dynamic config
         */
        set: <C, V>(theConfig: C, name: string, value: V) => V;
        /**
         * Set default values for the config if not present.
         * @param theConfig - The configuration object to set default on (if missing)
         * @param defaultValues - The default values to apply to the config
         */
        setDf: <C>(theConfig: C, defaultValues: IConfigDefaults<C>) => C;
        /**
         * Set this named property of the target as referenced, which will cause any object or array instance
         * to be updated in-place rather than being entirely replaced. All other values will continue to be replaced.
         * @returns The referenced properties current value
         */
        ref: <C, V = any>(target: C, name: string) => V;
        /**
         * Set this named property of the target as read-only, which will block this single named property from
         * ever being changed for the target instance.
         * This does NOT freeze or seal the instance, it just stops the direct re-assignment of the named property,
         * if the value is a non-primitive (ie. an object or array) it's properties will still be mutable.
         * @returns The referenced properties current value
         */
        rdOnly: <C, V = any>(target: C, name: string) => V;
    }

    interface IWatcherHandler<T = IConfiguration> extends IUnloadHook {
        fn: WatcherFunction<T>;
        rm: () => void;
    }

    interface IXDomainRequest extends XMLHttpRequestEventTarget {
        readonly responseText: string;
        send(payload: string): void;
        open(method: string, url: string): void;
        timeout: number;
        contentType: string;
        addEventListener(type: "error", listener: (ev: ErrorEvent) => any, useCapture?: boolean): void;
        addEventListener(type: "load" | "timeout", listener: (ev: Event) => any, useCapture?: boolean): void;
        addEventListener(type: "progress", listener: (ev: ProgressEvent) => any, useCapture?: boolean): void;
    }

    /**
     * The IXHROverride interface overrides the way HTTP requests are sent.
     */
    interface IXHROverride {
        sendPOST: SendPOSTFunction;
    }

    const LoggingSeverity: EnumValue<typeof eLoggingSeverity>;

    type LoggingSeverity = number | eLoggingSeverity;

    /**
     * Logs a message to the internal queue.
     * @param logger - The Diagnostic Logger instance to use.
     * @param severity  - The severity of the log message
     * @param message - The message to log.
     */
    function _logInternalMessage(logger: IDiagnosticLogger, severity: LoggingSeverity, message: _InternalLogMessage): void;

    function mergeEvtNamespace(theNamespace: string, namespaces?: string | string[] | null): string | string[];

    const MinChannelPriorty: number;

    function newGuid(): string;

    /**
     * Generate random base64 id string.
     * The default length is 22 which is 132-bits so almost the same as a GUID but as base64 (the previous default was 5)
     * @param maxLength - Optional value to specify the length of the id to be generated, defaults to 22
     */
    function newId(maxLength?: number): string;

    /**
     * Validates that the string name conforms to the JS IdentifierName specification and if not
     * normalizes the name so that it would. This method does not identify or change any keywords
     * meaning that if you pass in a known keyword the same value will be returned.
     * This is a simplified version
     * @param name - The name to validate
     */
    function normalizeJsName(name: string): string;

    /**
     * Class to manage sending notifications to all the listeners.
     */
    class NotificationManager implements INotificationManager {
        readonly listeners: INotificationListener[];
        constructor(config?: IConfiguration);
        /**
         * Adds a notification listener.
         * @param listener - The notification listener to be added.
         */
        addNotificationListener(listener: INotificationListener): void;
        /**
         * Removes all instances of the listener.
         * @param listener - AWTNotificationListener to remove.
         */
        removeNotificationListener(listener: INotificationListener): void;
        /**
         * Notification for events sent.
         * @param events - The array of events that have been sent.
         */
        eventsSent(events: ITelemetryItem[]): void;
        /**
         * Notification for events being discarded.
         * @param events - The array of events that have been discarded by the SDK.
         * @param reason - The reason for which the SDK discarded the events. The EventsDiscardedReason
         * constant should be used to check the different values.
         */
        eventsDiscarded(events: ITelemetryItem[], reason: number, sendType?: number): void;
        /**
         * [Optional] A function called when the events have been requested to be sent to the sever.
         * @param sendReason - The reason why the event batch is being sent.
         * @param isAsync - A flag which identifies whether the requests are being sent in an async or sync manner.
         */
        eventsSendRequest?(sendReason: number, isAsync: boolean): void;
        /**
         * Notification for events being retried.
         * @param events - The array of events that are being retried.
         * @param statusCode - The HTTP status code that triggered the retry.
         */
        eventsRetry?(events: ITelemetryItem[], statusCode: number): void;
        /**
         * [Optional] This event is sent if you have enabled perf events, they are primarily used to track internal performance testing and debugging
         * the event can be displayed via the debug plugin extension.
         * @param perfEvent - The performance event object containing relevant performance data.
         */
        perfEvent?(perfEvent: IPerfEvent): void;
        /**
         * Unload and remove any state that this INotificationManager may be holding, this is generally called when the
         * owning SDK is being unloaded.
         * @param isAsync - Can the unload be performed asynchronously (default)
         * @returns If the unload occurs synchronously then nothing should be returned, if happening asynchronously then
         * the function should return an [IPromise](https://nevware21.github.io/ts-async/typedoc/interfaces/IPromise.html)
         * / Promise to allow any listeners to wait for the operation to complete.
         */
        unload?(isAsync?: boolean): void | IPromise<void>;
        /**
         * [Optional] A function called when the offline events have been stored to the persistent storage
         * @param events - events that are stored in the persistent storage
         */
        offlineEventsStored?(events: ITelemetryItem[]): void;
        /**
         * [Optional] A function called when the offline events have been sent from the persistent storage
         * @param batch - payload data that is sent from the persistent storage
         */
        offlineBatchSent?(batch: IPayloadData): void;
        /**
         * [Optional] A function called when the offline events have been dropped from the persistent storage
         * @param cnt - count of batches dropped
         * @param reason - the reason why the batches is dropped
         * @since v3.1.1
         */
        offlineBatchDrop?(cnt: number, reason?: number): void;
    }

    /**
     * Try to define get/set object property accessors for the target object/prototype, this will provide compatibility with
     * existing API definition when run within an ES5+ container that supports accessors but still enable the code to be loaded
     * and executed in an ES3 container, providing basic IE8 compatibility.
     * @deprecated It is recommended that you use {@link objDefine} instead {@link objDefineAccessors} as this internally creates
     * the {@link ObjDefinePropDescriptor} definition based on your provided arguments. And only using a minimum set of functions
     * reduces your overall bundle size.
     * @group Object
     * @param target - The object on which to define the property.
     * @param prop - The name of the property to be defined or modified.
     * @param getProp - The getter function to wire against the getter.
     * @param setProp - The setter function to wire against the setter.
     * @param configurable - Can the value be changed, defaults to true
     * @param enumerable - Should this get property be enumerable, defaults to true.
     * @returns The object that was passed to the function
     */
    function objDefineAccessors<T, V = any>(target: T, prop: PropertyKey, getProp?: (() => V) | null, setProp?: ((v: V) => void) | null, configurable?: boolean, enumerable?: boolean): T;

    /**
     * Calls the provided `callbackFn` function once for each key in an object. This is equivalent to `arrForEach(Object.keys(theObject), callbackFn)` or
     * if not using the array helper `Object.keys(theObject).forEach(callbackFn)` except that this helper avoids creating a temporary array of the object
     * keys before iterating over them and like the `arrForEach` helper you CAN stop or break the iteration by returning -1 from the `callbackFn` function.
     *
     * **Note:** This helper only iterates string (and numeric) keys (via for...in loop) and does NOT include enumerable symbol keys.
     * If you need to iterate all keys including symbol, use {@link forEachOwnKey} or {@link forEachOwnKeySafe} instead.
     *
     * Caution: this helper does not filter unsafe keys like `__proto__`, `constructor`, or `prototype`.
     * If your callback uses the returned key to assign directly to another object (for example
     * `target[key] = value`), validate keys first (for example with {@link isUnsafePropKey}) or
     * use {@link objForEachKeySafe} when iterating untrusted input.
     * @group Object
     * @typeParam T - The object type
     * @param theObject - The object to iterate over
     * @param callbackfn - A function that accepts up to two arguments, the key name and the current value of the property represented by the key.
     * @param thisArg - [Optional] An object to which the this keyword can refer in the callbackfn function. If thisArg is omitted, null or undefined
     * the object will be used as the this value.
     * @example
     * ```ts
     * // Basic iteration - only string keys
     * const obj = { name: "Alice", age: 30 };
     * objForEachKey(obj, (key, value) => {
     *     console.log(key, value);  // name Alice, age 30
     * });
     * ```
     * @example
     * ```ts
     * // Unsafe keys warning - use objForEachKeySafe for untrusted input
     * // Note: use Object.defineProperty (not an object literal) so "__proto__" is
     * // created as a normal own enumerable property rather than being treated
     * // specially by the JS engine.
     * const untrustedObj: any = { name: "Bob" };
     * Object.defineProperty(untrustedObj, "__proto__", { value: "attack", enumerable: true, configurable: true, writable: true });
     * objForEachKey(untrustedObj, (key, value) => {
     *     console.log(key, value);  // name Bob, __proto__ attack (UNSAFE!)
     * });
     *
     * // Safe iteration with objForEachKeySafe
     * objForEachKeySafe(untrustedObj, (key, value) => {
     *     console.log(key, value);  // name Bob (unsafe keys filtered)
     * });
     * ```
     * @see {@link objForEachKeySafe} for safe iteration that filters unsafe keys
     * @see {@link forEachOwnKey} for iteration that includes both string and symbol keys
     * @see {@link forEachOwnKeySafe} for safe iteration with both string and symbol keys
     */
    function objForEachKey<T>(theObject: T, callbackfn: (key: string, value: T[keyof T]) => void | number, thisArg?: any): void;

    /**
     * The `objFreeze()` method freezes an object. A frozen object can no longer be changed; freezing an object
     * prevents new properties from being added to it, existing properties from being removed, prevents changing the
     * enumerability, configurability, or writability of existing properties, and prevents the values of existing
     * properties from being changed. In addition, freezing an object also prevents its prototype from being changed.
     * `objFreeze()` returns the same object that was passed in.
     *
     * Nothing can be added to or removed from the properties set of a frozen object. Any attempt to do so will fail,
     * either silently or by throwing a TypeError exception (most commonly, but not exclusively, when in strict mode).
     *
     * For data properties of a frozen object, values cannot be changed, the writable and configurable attributes are
     * set to false. Accessor properties (getters and setters) work the same (and still give the illusion that you are
     * changing the value). Note that values that are objects can still be modified, unless they are also frozen. As
     * an object, an array can be frozen; after doing so, its elements cannot be altered and no elements can be added
     * to or removed from the array.
     *
     * `objFreeze()` returns the same object that was passed into the function. It does not create a frozen copy.
     * @function
     * @group Object
     * @param value - The object to freeze.
     * @returns The object that was passed to the function.
     */
    const objFreeze: <T>(value: T) => T;

    /**
     * The `objKeys()` method returns an array of a given object's own enumerable property names, iterated in
     * the same order that a normal loop would.
     *
     * objKeys() returns an array whose elements are strings corresponding to the enumerable properties found
     * directly upon object. The ordering of the properties is the same as that given by looping over the
     * properties of the object manually.
     * @function
     * @group Object
     * @param value - The object to obtain a copy of the keys from
     * @returns An array of the properties names for the value object.
     * @example
     * ```ts
     * // simple array
     * const arr = ['a', 'b', 'c'];
     * console.log(objKeys(arr)); // console: ['0', '1', '2']
     *
     * // array-like object
     * const obj = { 0: 'a', 1: 'b', 2: 'c' };
     * console.log(objKeys(obj)); // console: ['0', '1', '2']
     *
     * // array-like object with random key ordering
     * const anObj = { 100: 'a', 2: 'b', 7: 'c' };
     * console.log(objKeys(anObj)); // console: ['2', '7', '100']
     *
     * // getFoo is a property which isn't enumerable
     * const myObj = objCreate({}, {
     *   getFoo: {
     *     value() { return this.foo; }
     *   }
     * });
     * myObj.foo = 1;
     * console.log(objKeys(myObj)); // console: ['foo']
     * ```
     */
    const objKeys: (value: any) => string[];

    /**
     * The `objSeal()` method seals an object, preventing new properties from being added to it and marking all
     * existing properties as non-configurable. Values of present properties can still be changed as long as they
     * are writable.
     * @function
     * @group Object
     * @param value - The object which should be sealed.
     * @returns The object being sealed.
     */
    const objSeal: <T>(value: T) => T;

